INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p135-7', 'doc-14-nist-sp-800-53', '', 135, 'Control Enhancements: (1) SYSTEM COMPONENT INVENTORY | UPDATES DURING INSTALLATION AND REMOVAL Update the inventory of system components as part of component installations, removals, and system updates.', 'kb-doc-14-nist-sp-800-53-p135-7', 0, 27, '14-nist-sp-800-53', 'retrieved', 'B7B0A835609FF23001E4A6D6041CB4BD0BC7F5A33E6D2BBDAA2ABF7146B29CB0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p135-8', 'doc-14-nist-sp-800-53', '', 135, 'Discussion: Organizations can improve the accuracy, completeness, and consistency of system component inventories if the inventories are updated as part of component installations or removals or during general system updates. If inventories are not updated at these key times, there is a greater likelihood that the information will not be appropriately captured and documented. System updates include hardware, software, and firmware components.', 'kb-doc-14-nist-sp-800-53-p135-8', 0, 62, '14-nist-sp-800-53', 'retrieved', '0092629DE38C422FF430DE5D4F6EDFB25C04B3C3CCAE72FE920B5CB42AC38820', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p135-10', 'doc-14-nist-sp-800-53', '', 135, '(2) SYSTEM COMPONENT INVENTORY | AUTOMATED MAINTENANCE Maintain the currency, completeness, accuracy, and availability of the inventory of system components using [Assignment: organization-defined automated mechanisms].', 'kb-doc-14-nist-sp-800-53-p135-10', 0, 25, '14-nist-sp-800-53', 'retrieved', '1FDECB245F0ACC8A94F7B19FF6FD1C018E5D02A12A000E2C8E05E5FA17AE22AF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p135-11', 'doc-14-nist-sp-800-53', '', 135, 'Discussion: Organizations maintain system inventories to the extent feasible. For example, virtual machines can be difficult to monitor because such machines are not visible to the network when not in use. In such cases, organizations maintain as up-to-date, complete, and', 'kb-doc-14-nist-sp-800-53-p135-11', 0, 40, '14-nist-sp-800-53', 'retrieved', '74C0995D963CE475A174E324601E829396A304459E31B473E17F403F43DEC66F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p136-1', 'doc-14-nist-sp-800-53', '', 136, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 109 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p136-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '98B24EC08A60A107EEDF8D631E4797AE7ADAC855FD3A48CCA630AFED7545C6A6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
