INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p136-2', 'doc-14-nist-sp-800-53', '', 136, 'accurate an inventory as is deemed reasonable. Automated maintenance can be achieved by the implementation of CM-2(2) for organizations that combine system component inventory and baseline configuration activities.', 'kb-doc-14-nist-sp-800-53-p136-2', 0, 28, '14-nist-sp-800-53', 'retrieved', '24AE91EF773C2FF30DCECA2CA5E76DFAD77943370CEA0A4801D5ED6DF3375844', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
