INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p136-10', 'doc-14-nist-sp-800-53', '', 136, 'Discussion: Assessed configurations and approved deviations focus on configuration settings established by organizations for system components, the specific components that have been assessed to determine compliance with the required configuration settings, and any approved deviations from established configuration settings.', 'kb-doc-14-nist-sp-800-53-p136-10', 0, 39, '14-nist-sp-800-53', 'retrieved', '279F980B13533AAFFD44FD8DA06E4DF1BF3AE601D1010A1C02F60395DD8F1D62', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
