VALUES ('doc-14-nist-sp-800-53-p136-12', 'doc-14-nist-sp-800-53', '', 136, '(7) SYSTEM COMPONENT INVENTORY | CENTRALIZED REPOSITORY Provide a centralized repository for the inventory of system components.', 'kb-doc-14-nist-sp-800-53-p136-12', 0, 17, '14-nist-sp-800-53', 'retrieved', '244E2783067363E6DE5E497D1AB3B14ECC4728AF3C1632F5B14C9F973895F9E5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
