VALUES ('doc-14-nist-sp-800-53-p137-1', 'doc-14-nist-sp-800-53', '', 137, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 110 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p137-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '2A6C0B18F0A760D75CF13CBD25F77A2151811929F5AFDF83640182C366D1E7F1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
