INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p137-8', 'doc-14-nist-sp-800-53', '', 137, 'Discussion: System components that are not assigned to a system may be unmanaged, lack the required protection, and become an organizational vulnerability.', 'kb-doc-14-nist-sp-800-53-p137-8', 0, 22, '14-nist-sp-800-53', 'retrieved', 'FBF759B9FE213B540F0394DB086E1EC62D937B229688D525A4BAC40D6D1CB383', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
