VALUES ('doc-14-nist-sp-800-53-p137-10', 'doc-14-nist-sp-800-53', '', 137, 'References: [OMB A-130], [SP 800-57-1], [SP 800-57-2], [SP 800-57-3], [SP 800-128], [IR 8011-2], [IR 8011-3].', 'kb-doc-14-nist-sp-800-53-p137-10', 0, 15, '14-nist-sp-800-53', 'retrieved', '3E8553734826DCA315D1FD4705E41A8EC93079BDE4F8CDA37A969A81125E420C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
