VALUES ('doc-14-nist-sp-800-53-p138-1', 'doc-14-nist-sp-800-53', '', 138, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 111 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p138-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '1AAC8707EF88B876D78D078DF0FBC1FEF38EA72168761EE5ABF0D42073C3AF2F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
