VALUES ('doc-14-nist-sp-800-53-p139-1', 'doc-14-nist-sp-800-53', '', 139, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 112 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p139-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '7B1C23C0CFE8FEFA8CD85759E5A75F2545B9FE934B60EE9CE02AEE315809614F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
