INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p139-3', 'doc-14-nist-sp-800-53', '', 139, 'Discussion: Open-source software refers to software that is available in source code form.', 'kb-doc-14-nist-sp-800-53-p139-3', 0, 13, '14-nist-sp-800-53', 'retrieved', '603B6EAC1383694C4AB1E4B1FEEDD05A878DD0C3C40D58ED3D5AF2A64B40A8AB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p139-4', 'doc-14-nist-sp-800-53', '', 139, 'Certain software rights normally reserved for copyright holders are routinely provided under software license agreements that permit individuals to study, change, and improve the software. From a security perspective, the major advantage of open-source software is that it provides organizations with the ability to examine the source code. In some cases, there is an online community associated with the software that inspects, tests, updates, and reports on issues found in software on an ongoing basis. However, remediating vulnerabilities in open-source software may be problematic. There may also be licensing issues associated with open-source software, including the constraints on derivative use of such software.', 'kb-doc-14-nist-sp-800-53-p139-4', 0, 103, '14-nist-sp-800-53', 'retrieved', 'B3D910901DF8D3C68F105F436714891E5D9B65910936A0BE0858AE63766A2949', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
