INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p139-5', 'doc-14-nist-sp-800-53', '', 139, 'Open-source software that is available only in binary form may increase the level of risk in using such software.', 'kb-doc-14-nist-sp-800-53-p139-5', 0, 19, '14-nist-sp-800-53', 'retrieved', 'D0B12906934FEB8B552AD41FC3AD2F7E7755C1D7DF59AAD57123D3ED1271E326', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
