INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p139-8', 'doc-14-nist-sp-800-53', '', 139, 'CM-11 USER-INSTALLED SOFTWARE Control: a. Establish [Assignment: organization-defined policies] governing the installation of software by users; b. Enforce software installation policies through the following methods: [Assignment: organization-defined methods]; and c. Monitor policy compliance [Assignment: organization-defined frequency].', 'kb-doc-14-nist-sp-800-53-p139-8', 0, 36, '14-nist-sp-800-53', 'retrieved', '2DF2793168664744D482102F5BDD78E5B0F71FD87B18ED27DD7B93C664E1DF98', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
