INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p139-9', 'doc-14-nist-sp-800-53', '', 139, 'Discussion: If provided the necessary privileges, users can install software in organizational systems. To maintain control over the software installed, organizations identify permitted and prohibited actions regarding software installation. Permitted software installations include updates and security patches to existing software and downloading new applications from organization-approved “app stores.” Prohibited software installations include software with unknown or suspect pedigrees or software that organizations consider potentially malicious.', 'kb-doc-14-nist-sp-800-53-p139-9', 0, 65, '14-nist-sp-800-53', 'retrieved', '289E0731DC90A7B1083634C315B92259E67C9A5808E2F1016E2B4C8A45ACA8AC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p139-10', 'doc-14-nist-sp-800-53', '', 139, 'Policies selected for governing user-installed software are organization-developed or provided by some external entity. Policy enforcement methods can include procedural methods and automated methods.', 'kb-doc-14-nist-sp-800-53-p139-10', 0, 24, '14-nist-sp-800-53', 'retrieved', '04DFAFE139C88E7F0C54F1072C0578C99F47724E7C5C8737AA4F5DFF94F0B5B9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
