VALUES ('doc-14-nist-sp-800-53-p139-12', 'doc-14-nist-sp-800-53', '', 139, 'Control Enhancements: (1) USER-INSTALLED SOFTWARE | ALERTS FOR UNAUTHORIZED INSTALLATIONS [Withdrawn: Incorporated into CM-8(3).] (2) USER-INSTALLED SOFTWARE | SOFTWARE INSTALLATION WITH PRIVILEGED STATUS Allow user installation of software only with explicit privileged status.', 'kb-doc-14-nist-sp-800-53-p139-12', 0, 33, '14-nist-sp-800-53', 'retrieved', 'A813C3F8BFDC248BF0C187885E20610D68F644332E3878F00B0D13CA2D7E8579', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
