INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p139-13', 'doc-14-nist-sp-800-53', '', 139, 'Discussion: Privileged status can be obtained, for example, by serving in the role of system administrator.', 'kb-doc-14-nist-sp-800-53-p139-13', 0, 16, '14-nist-sp-800-53', 'retrieved', '1DE0B45119B5F11873003DB63F73EB43C906357FE46DBDC1C1B466951776C8D9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
