VALUES ('doc-14-nist-sp-800-53-p140-1', 'doc-14-nist-sp-800-53', '', 140, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 113 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p140-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'C79A56B5A6C8943C1AD8FB190DC0A442CA4EDE3AB847B4769AE9EEB8FE1F11AA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
