INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p140-2', 'doc-14-nist-sp-800-53', '', 140, 'Enforce and monitor compliance with software installation policies using [Assignment: organization-defined automated mechanisms].', 'kb-doc-14-nist-sp-800-53-p140-2', 0, 13, '14-nist-sp-800-53', 'retrieved', '2C0B1053D4023DFD90B588C1011755F4FE3FFD1B82726D30219B5652F46332FA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
