INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p140-3', 'doc-14-nist-sp-800-53', '', 140, 'Discussion: Organizations enforce and monitor compliance with software installation policies using automated mechanisms to more quickly detect and respond to unauthorized software installation which can be an indicator of an internal or external hostile attack.', 'kb-doc-14-nist-sp-800-53-p140-3', 0, 35, '14-nist-sp-800-53', 'retrieved', 'A2481E2518767945C0688A2D8BE335231117F8EA4609E487D84AAB8B410611FB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
