VALUES ('doc-14-nist-sp-800-53-p140-8', 'doc-14-nist-sp-800-53', '', 140, 'Related Controls: AC-2, AC-3, AC-4, AC-6, AC-23, CM-8, PM-5, RA-2, SA-4, SA-8, SA-17, SC-4, SC- 16, SC-28, SI-4, SI-7.', 'kb-doc-14-nist-sp-800-53-p140-8', 0, 19, '14-nist-sp-800-53', 'retrieved', 'B452E1C55AD3542A6D4F02A8C5A87C5C5B0EC512AA1CCC69B46AF54B752CCD31', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
