VALUES ('doc-14-nist-sp-800-53-p140-13', 'doc-14-nist-sp-800-53', '', 140, 'CM-13 DATA ACTION MAPPING Control: Develop and document a map of system data actions.', 'kb-doc-14-nist-sp-800-53-p140-13', 0, 14, '14-nist-sp-800-53', 'retrieved', '6EDBF05DA4D019BCB9BAB86353607F7EFD8C3914836A10BA75E59CADE49BB85A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
