INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p140-14', 'doc-14-nist-sp-800-53', '', 140, 'Discussion: Data actions are system operations that process personally identifiable information.', 'kb-doc-14-nist-sp-800-53-p140-14', 0, 11, '14-nist-sp-800-53', 'retrieved', 'F0FEDDD892BF10A6B8F249AD2E1F5B8DA69122B6654F43E9E4DB55D7B6CEF1C9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
