INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p140-15', 'doc-14-nist-sp-800-53', '', 140, 'The processing of such information encompasses the full information life cycle, which includes collection, generation, transformation, use, disclosure, retention, and disposal. A map of system', 'kb-doc-14-nist-sp-800-53-p140-15', 0, 25, '14-nist-sp-800-53', 'retrieved', 'D968A1A9E9DE296D9D2A2834C9BF7CB3FC1E952EF426823392486184FDD1A9D7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
