VALUES ('doc-14-nist-sp-800-53-p143-1', 'doc-14-nist-sp-800-53', '', 143, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 116 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p143-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'F9E56C81CCBE456048D322E4AC38F720BE57312D2D7EDD3FB428DCA09CE51F71', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
