INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p144-3', 'doc-14-nist-sp-800-53', '', 144, 'Control Enhancements: (1) CONTINGENCY PLAN | COORDINATE WITH RELATED PLANS Coordinate contingency plan development with organizational elements responsible for related plans.', 'kb-doc-14-nist-sp-800-53-p144-3', 0, 21, '14-nist-sp-800-53', 'retrieved', '1BA43BBAF346400B7E22F62FE24F80DDA486294D56E5E2D2488637E013B34820', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
