INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p144-4', 'doc-14-nist-sp-800-53', '', 144, 'Discussion: Plans that are related to contingency plans include Business Continuity Plans, Disaster Recovery Plans, Critical Infrastructure Plans, Continuity of Operations Plans, Crisis Communications Plans, Insider Threat Implementation Plans, Data Breach Response Plans, Cyber Incident Response Plans, Breach Response Plans, and Occupant Emergency Plans.', 'kb-doc-14-nist-sp-800-53-p144-4', 0, 44, '14-nist-sp-800-53', 'retrieved', '502CDD5B8DE458F733262A6203BB87A6BDFC9C5815FB27DC8AA6424F45E01C30', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p144-6', 'doc-14-nist-sp-800-53', '', 144, '(2) CONTINGENCY PLAN | CAPACITY PLANNING Conduct capacity planning so that necessary capacity for information processing, telecommunications, and environmental support exists during contingency operations.', 'kb-doc-14-nist-sp-800-53-p144-6', 0, 24, '14-nist-sp-800-53', 'retrieved', '8A32FC6E8D52B646F9B34F10B75EF18B36A3F7005E965218CF800683782AE08B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p144-7', 'doc-14-nist-sp-800-53', '', 144, 'Discussion: Capacity planning is needed because different threats can result in a reduction of the available processing, telecommunications, and support services intended to support essential mission and business functions. Organizations anticipate degraded operations during contingency operations and factor the degradation into capacity planning. For capacity planning, environmental support refers to any environmental factor for which the organization determines that it needs to provide support in a contingency situation, even if in a degraded state. Such determinations are based on an organizational assessment of risk, system categorization (impact level), and organizational risk tolerance.', 'kb-doc-14-nist-sp-800-53-p144-7', 0, 92, '14-nist-sp-800-53', 'retrieved', '24E2097EABA115FBEF7C1A2AC747B7889ABAED4E26F3C34ADDF387BC48AB5C1A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p144-9', 'doc-14-nist-sp-800-53', '', 144, '(3) CONTINGENCY PLAN | RESUME MISSION AND BUSINESS FUNCTIONS Plan for the resumption of [Selection: all; essential] mission and business functions within [Assignment: organization-defined time period] of contingency plan activation.', 'kb-doc-14-nist-sp-800-53-p144-9', 0, 30, '14-nist-sp-800-53', 'retrieved', '816A453D3238FDB6DB5FD0068744DC15640643D74B637FE6B5ACCDDEAD2E713F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p144-10', 'doc-14-nist-sp-800-53', '', 144, 'Discussion: Organizations may choose to conduct contingency planning activities to resume mission and business functions as part of business continuity planning or as part of business impact analyses. Organizations prioritize the resumption of mission and business functions.', 'kb-doc-14-nist-sp-800-53-p144-10', 0, 37, '14-nist-sp-800-53', 'retrieved', 'FA828EFC16E26DE44CCF8D23B2EA5D0786150329BB15B178807DB85A4759C2FF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p144-11', 'doc-14-nist-sp-800-53', '', 144, 'The time period for resuming mission and business functions may be dependent on the severity and extent of the disruptions to the system and its supporting infrastructure.', 'kb-doc-14-nist-sp-800-53-p144-11', 0, 27, '14-nist-sp-800-53', 'retrieved', 'C44EF425EBF6C39C7A5DBFB6A57C2F3D3F707C6544540D32F660F2C1BE1A91A6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p144-13', 'doc-14-nist-sp-800-53', '', 144, '(4) CONTINGENCY PLAN | RESUME ALL MISSION AND BUSINESS FUNCTIONS [Withdrawn: Incorporated into CP-2(3).] (5) CONTINGENCY PLAN | CONTINUE MISSION AND BUSINESS FUNCTIONS Plan for the continuance of [Selection: all; essential] mission and business functions with minimal or no loss of operational continuity and sustains that continuity until full system restoration at primary processing and/or storage sites.', 'kb-doc-14-nist-sp-800-53-p144-13', 0, 57, '14-nist-sp-800-53', 'retrieved', 'E5AA436E21074610D8A7E5FAC95DA5A5F1E29C18D2BDC26DB8756780F784AB40', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p144-14', 'doc-14-nist-sp-800-53', '', 144, 'Discussion: Organizations may choose to conduct the contingency planning activities to continue mission and business functions as part of business continuity planning or business impact analyses. Primary processing and/or storage sites defined by organizations as part of contingency planning may change depending on the circumstances associated with the contingency.', 'kb-doc-14-nist-sp-800-53-p144-14', 0, 49, '14-nist-sp-800-53', 'retrieved', 'CFC816072EDC9412086EAAF7024ACAA615E4EE36370D9C450FE01AFF38C4830E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
