VALUES ('doc-14-nist-sp-800-53-p145-1', 'doc-14-nist-sp-800-53', '', 145, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 118 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p145-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '3B7ABFB5D6002BEE5F63CF0812E1311665CE982E07B8D286EA08D9D8C07E83E5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
