INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p145-3', 'doc-14-nist-sp-800-53', '', 145, 'Discussion: Organizations may choose to conduct contingency planning activities for alternate processing and storage sites as part of business continuity planning or business impact analyses. Primary processing and/or storage sites defined by organizations as part of contingency planning may change depending on the circumstances associated with the contingency.', 'kb-doc-14-nist-sp-800-53-p145-3', 0, 48, '14-nist-sp-800-53', 'retrieved', 'B2C3DF1A5113643EC489075E1D10902CD036FD6A641C628EFDF5174130F6A3F5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
