INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p146-2', 'doc-14-nist-sp-800-53', '', 146, '3. [Assignment: organization-defined frequency] thereafter; and b. Review and update contingency training content [Assignment: organization-defined frequency] and following [Assignment: organization-defined events].', 'kb-doc-14-nist-sp-800-53-p146-2', 0, 21, '14-nist-sp-800-53', 'retrieved', '144102860345A598D8A6962D54B1344D97B86382F9DB705DCF51B7A18C5AF3B1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
