INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p146-12', 'doc-14-nist-sp-800-53', '', 146, 'CP-4 CONTINGENCY PLAN TESTING Control: a. Test the contingency plan for the system [Assignment: organization-defined frequency] using the following tests to determine the effectiveness of the plan and the readiness to execute the plan: [Assignment: organization-defined tests].', 'kb-doc-14-nist-sp-800-53-p146-12', 0, 37, '14-nist-sp-800-53', 'retrieved', 'F99969CB42608A59D4FFFCFB1EC3192D269A22775044B5312D21AEFC707114AC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
