VALUES ('doc-14-nist-sp-800-53-p147-1', 'doc-14-nist-sp-800-53', '', 147, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 120 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p147-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '2F8AD59297E33C589A867468595F187F590E28482A26AE76C676D12B8D6B3D9F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
