INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p147-3', 'doc-14-nist-sp-800-53', '', 147, 'Discussion: Methods for testing contingency plans to determine the effectiveness of the plans and identify potential weaknesses include checklists, walk-through and tabletop exercises, simulations (parallel or full interrupt), and comprehensive exercises. Organizations conduct testing based on the requirements in contingency plans and include a determination of the effects on organizational operations, assets, and individuals due to contingency operations.', 'kb-doc-14-nist-sp-800-53-p147-3', 0, 58, '14-nist-sp-800-53', 'retrieved', '4471DF189C9B59B50E45906F74CA2A05DC168CA2B6E9713C2DF9B7C48D37861E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p147-4', 'doc-14-nist-sp-800-53', '', 147, 'Organizations have flexibility and discretion in the breadth, depth, and timelines of corrective actions.', 'kb-doc-14-nist-sp-800-53-p147-4', 0, 14, '14-nist-sp-800-53', 'retrieved', 'C083C901E6F5C83F9C1A151E8411435A4E352816516BCA0248D104E871574A57', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
