INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p147-6', 'doc-14-nist-sp-800-53', '', 147, 'Control Enhancements: (1) CONTINGENCY PLAN TESTING | COORDINATE WITH RELATED PLANS Coordinate contingency plan testing with organizational elements responsible for related plans.', 'kb-doc-14-nist-sp-800-53-p147-6', 0, 22, '14-nist-sp-800-53', 'retrieved', '9F82D65CC8243B808673B5D71CDC9DD2736D38F8918395D045C3EDA24F07FC4D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
