INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p147-7', 'doc-14-nist-sp-800-53', '', 147, 'Discussion: Plans related to contingency planning for organizational systems include Business Continuity Plans, Disaster Recovery Plans, Continuity of Operations Plans, Crisis Communications Plans, Critical Infrastructure Plans, Cyber Incident Response Plans, and Occupant Emergency Plans. Coordination of contingency plan testing does not require organizations to create organizational elements to handle related plans or to align such elements with specific plans. However, it does require that if such organizational elements are responsible for related plans, organizations coordinate with those elements.', 'kb-doc-14-nist-sp-800-53-p147-7', 0, 78, '14-nist-sp-800-53', 'retrieved', '683080A4ACB9A907EDBE50152A5A032CDE76427A2147BDE250DF32A21C7545F8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p147-9', 'doc-14-nist-sp-800-53', '', 147, '(2) CONTINGENCY PLAN TESTING | ALTERNATE PROCESSING SITE Test the contingency plan at the alternate processing site: (a) To familiarize contingency personnel with the facility and available resources; and (b) To evaluate the capabilities of the alternate processing site to support contingency operations.', 'kb-doc-14-nist-sp-800-53-p147-9', 0, 43, '14-nist-sp-800-53', 'retrieved', 'F1B6DDB05064D8EAA26AC3BB75D3D19D28B31E7F546416232BE702518A4140A9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p147-10', 'doc-14-nist-sp-800-53', '', 147, 'Discussion: Conditions at the alternate processing site may be significantly different than the conditions at the primary site. Having the opportunity to visit the alternate site and experience the actual capabilities available at the site can provide valuable information on potential vulnerabilities that could affect essential organizational mission and business functions. The on-site visit can also provide an opportunity to refine the contingency plan to address the vulnerabilities discovered during testing.', 'kb-doc-14-nist-sp-800-53-p147-10', 0, 71, '14-nist-sp-800-53', 'retrieved', 'E2CE7D90CD1B6D4465B738446443E43463F795A4154424258E2D5FA8A3540062', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p147-12', 'doc-14-nist-sp-800-53', '', 147, '(3) CONTINGENCY PLAN TESTING | AUTOMATED TESTING Test the contingency plan using [Assignment: organization-defined automated mechanisms].', 'kb-doc-14-nist-sp-800-53-p147-12', 0, 16, '14-nist-sp-800-53', 'retrieved', 'CDAA25D3D7BA1FD67FCA92562618C083397423E65A3492DBA4C9C17CF6708D6F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
