INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p147-13', 'doc-14-nist-sp-800-53', '', 147, 'Discussion: Automated mechanisms facilitate thorough and effective testing of contingency plans by providing more complete coverage of contingency issues, selecting more realistic test scenarios and environments, and effectively stressing the system and supported mission and business functions.', 'kb-doc-14-nist-sp-800-53-p147-13', 0, 37, '14-nist-sp-800-53', 'retrieved', '9D566FF36C6D57B8E3FE67009AD114D373C4EEE4F2404F5E7A65D7043A60A54D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p147-15', 'doc-14-nist-sp-800-53', '', 147, '(4) CONTINGENCY PLAN TESTING | FULL RECOVERY AND RECONSTITUTION Include a full recovery and reconstitution of the system to a known state as part of contingency plan testing.', 'kb-doc-14-nist-sp-800-53-p147-15', 0, 28, '14-nist-sp-800-53', 'retrieved', 'AB431CA63C30982EB4DEE02B8B950854A68BFD063F11F3BE945DAFB9748F3675', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
