INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p147-16', 'doc-14-nist-sp-800-53', '', 147, 'Discussion: Recovery is executing contingency plan activities to restore organizational mission and business functions. Reconstitution takes place following recovery and includes', 'kb-doc-14-nist-sp-800-53-p147-16', 0, 21, '14-nist-sp-800-53', 'retrieved', '343CBCCF1EE72898E0C3929DDCC0292C257E5AD59383A7EE49EFF704ECCB2498', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
