INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p148-12', 'doc-14-nist-sp-800-53', '', 148, 'Control Enhancements: (1) ALTERNATE STORAGE SITE | SEPARATION FROM PRIMARY SITE Identify an alternate storage site that is sufficiently separated from the primary storage site to reduce susceptibility to the same threats.', 'kb-doc-14-nist-sp-800-53-p148-12', 0, 32, '14-nist-sp-800-53', 'retrieved', '0F343B6F813D1639AF9250983FE5F9A1067FF4AB2F3AB1371457169524DBF676', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p148-13', 'doc-14-nist-sp-800-53', '', 148, 'Discussion: Threats that affect alternate storage sites are defined in organizational risk assessments and include natural disasters, structural failures, hostile attacks, and errors of', 'kb-doc-14-nist-sp-800-53-p148-13', 0, 24, '14-nist-sp-800-53', 'retrieved', 'CFE02EC5CEDDA0409A394C274943309DC4939FF6A65764965CB54EF63F1D0AED', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
