VALUES ('doc-14-nist-sp-800-53-p150-2', 'doc-14-nist-sp-800-53', '', 150, 'that reflect the requirements in contingency plans to maintain essential mission and business functions despite disruption, compromise, or failure in organizational systems.', 'kb-doc-14-nist-sp-800-53-p150-2', 0, 22, '14-nist-sp-800-53', 'retrieved', 'E8103E7966608E2837E8C4410D64223332B4C0700C2DF007592E27A1909344F4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
