VALUES ('doc-14-nist-sp-800-53-p150-3', 'doc-14-nist-sp-800-53', '', 150, 'Related Controls: CP-2, CP-6, CP-8, CP-9, CP-10, MA-6, PE-3, PE-11, PE-12, PE-17, SC-36, SI-13.', 'kb-doc-14-nist-sp-800-53-p150-3', 0, 14, '14-nist-sp-800-53', 'retrieved', 'B6ED1C629BE36B7E4023D2FFA50FF8DCA3ADC8C313BA5BEB1A51B6BFC9B103C9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
