INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p150-4', 'doc-14-nist-sp-800-53', '', 150, 'Control Enhancements: (1) ALTERNATE PROCESSING SITE | SEPARATION FROM PRIMARY SITE Identify an alternate processing site that is sufficiently separated from the primary processing site to reduce susceptibility to the same threats.', 'kb-doc-14-nist-sp-800-53-p150-4', 0, 32, '14-nist-sp-800-53', 'retrieved', '6C91741D9E06E39629E69A18E5D1A3427B7CC2DEA0C83483E1FA1D8626589D4B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p150-5', 'doc-14-nist-sp-800-53', '', 150, 'Discussion: Threats that affect alternate processing sites are defined in organizational assessments of risk and include natural disasters, structural failures, hostile attacks, and errors of omission or commission. Organizations determine what is considered a sufficient degree of separation between primary and alternate processing sites based on the types of threats that are of concern. For threats such as hostile attacks, the degree of separation between sites is less relevant.', 'kb-doc-14-nist-sp-800-53-p150-5', 0, 69, '14-nist-sp-800-53', 'retrieved', '6FE521502D12EBB3C57F31EB46D603523386794A3708BD601B3DD652B8E9B5A6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p150-7', 'doc-14-nist-sp-800-53', '', 150, '(2) ALTERNATE PROCESSING SITE | ACCESSIBILITY Identify potential accessibility problems to alternate processing sites in the event of an area-wide disruption or disaster and outlines explicit mitigation actions.', 'kb-doc-14-nist-sp-800-53-p150-7', 0, 28, '14-nist-sp-800-53', 'retrieved', '5E47E77F570B194BFDC44114BBEE9E17B0B290C06D503CE9BA97E6608DF0CC0D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p150-8', 'doc-14-nist-sp-800-53', '', 150, 'Discussion: Area-wide disruptions refer to those types of disruptions that are broad in geographic scope with such determinations made by organizations based on organizational assessments of risk.', 'kb-doc-14-nist-sp-800-53-p150-8', 0, 27, '14-nist-sp-800-53', 'retrieved', 'AF9E1D61B563516E976B8AA3E241625AFD4FD42EA718BB2CBFD60D8E0807BEB5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p150-10', 'doc-14-nist-sp-800-53', '', 150, '(3) ALTERNATE PROCESSING SITE | PRIORITY OF SERVICE Develop alternate processing site agreements that contain priority-of-service provisions in accordance with availability requirements (including recovery time objectives).', 'kb-doc-14-nist-sp-800-53-p150-10', 0, 26, '14-nist-sp-800-53', 'retrieved', 'E54408ED3FE68630FB0066CDDC669771D4EA9A3E0695E239DF010A01B9A328E7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p150-11', 'doc-14-nist-sp-800-53', '', 150, 'Discussion: Priority of service agreements refer to negotiated agreements with service providers that ensure that organizations receive priority treatment consistent with their availability requirements and the availability of information resources for logical alternate processing and/or at the physical alternate processing site. Organizations establish recovery time objectives as part of contingency planning.', 'kb-doc-14-nist-sp-800-53-p150-11', 0, 51, '14-nist-sp-800-53', 'retrieved', 'F82B2A5DD5972CCAA8886557093838ACCC081D6F02383966E3C928D0B15FA43D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p150-13', 'doc-14-nist-sp-800-53', '', 150, '(4) ALTERNATE PROCESSING SITE | PREPARATION FOR USE Prepare the alternate processing site so that the site can serve as the operational site supporting essential mission and business functions.', 'kb-doc-14-nist-sp-800-53-p150-13', 0, 29, '14-nist-sp-800-53', 'retrieved', '5A243C3B2590D55F6DD7DD62750E33B2A5C5BD152701EB4B6128D404AA172197', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p150-14', 'doc-14-nist-sp-800-53', '', 150, 'Discussion: Site preparation includes establishing configuration settings for systems at the alternate processing site consistent with the requirements for such settings at the primary site and ensuring that essential supplies and logistical considerations are in place.', 'kb-doc-14-nist-sp-800-53-p150-14', 0, 36, '14-nist-sp-800-53', 'retrieved', 'C0BBAA4BCFFBFB5471C5CBA64DB4212F53095B467C629778BA39561F5B8B78D4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p150-16', 'doc-14-nist-sp-800-53', '', 150, '(5) ALTERNATE PROCESSING SITE | EQUIVALENT INFORMATION SECURITY SAFEGUARDS [Withdrawn: Incorporated into CP-7.] (6) ALTERNATE PROCESSING SITE | INABILITY TO RETURN TO PRIMARY SITE Plan and prepare for circumstances that preclude returning to the primary processing site.', 'kb-doc-14-nist-sp-800-53-p150-16', 0, 37, '14-nist-sp-800-53', 'retrieved', 'E45C1C9EDDB523C5D4102938E6B97F2180FC307C144B1506D549A64240EA3C23', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p150-17', 'doc-14-nist-sp-800-53', '', 150, 'Discussion: There may be situations that preclude an organization from returning to the primary processing site such as if a natural disaster (e.g., flood or a hurricane) damaged or', 'kb-doc-14-nist-sp-800-53-p150-17', 0, 29, '14-nist-sp-800-53', 'retrieved', 'A436F6358BE2FB4C69ADA98E634C63F1E92D9FA6813B07E6344550CE21815A42', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p151-1', 'doc-14-nist-sp-800-53', '', 151, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 124 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p151-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'F1A18D45812087484D14351222C7002135D34751067C1BF8AEC2D45DFD992F33', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
