VALUES ('doc-14-nist-sp-800-53-p151-2', 'doc-14-nist-sp-800-53', '', 151, 'destroyed a facility and it was determined that rebuilding in the same location was not prudent.', 'kb-doc-14-nist-sp-800-53-p151-2', 0, 16, '14-nist-sp-800-53', 'retrieved', '19BC6C511D350978176143B73460975B07A6AA654879F3D119100FCB7005C192', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
