INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p152-3', 'doc-14-nist-sp-800-53', '', 152, '(3) TELECOMMUNICATIONS SERVICES | SEPARATION OF PRIMARY AND ALTERNATE PROVIDERS Obtain alternate telecommunications services from providers that are separated from primary service providers to reduce susceptibility to the same threats.', 'kb-doc-14-nist-sp-800-53-p152-3', 0, 30, '14-nist-sp-800-53', 'retrieved', '2AC09F9775604D7E2FED835621C550619EAFBAFDF01EC01A25B574B157A9B038', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
