INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p152-10', 'doc-14-nist-sp-800-53', '', 152, 'Discussion: Alternate telecommunications services testing is arranged through contractual agreements with service providers. The testing may occur in parallel with normal operations to ensure that there is no degradation in organizational missions or functions.', 'kb-doc-14-nist-sp-800-53-p152-10', 0, 34, '14-nist-sp-800-53', 'retrieved', '76DD12BD86A3DFBBC73B5399743DB04B461F64253C5E91A74A45B93C77222DF6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p152-13', 'doc-14-nist-sp-800-53', '', 152, 'CP-9 SYSTEM BACKUP Control: a. Conduct backups of user-level information contained in [Assignment: organization-defined system components] [Assignment: organization-defined frequency consistent with recovery time and recovery point objectives]; b. Conduct backups of system-level information contained in the system [Assignment: organization-defined frequency consistent with recovery time and recovery point objectives];', 'kb-doc-14-nist-sp-800-53-p152-13', 0, 48, '14-nist-sp-800-53', 'retrieved', '6853C3B34710CDD41BC09E3D675A9F105BDF78FD8144335A10BA6E99CECA3CB0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
