INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p153-5', 'doc-14-nist-sp-800-53', '', 153, 'Control Enhancements: (1) SYSTEM BACKUP | TESTING FOR RELIABILITY AND INTEGRITY Test backup information [Assignment: organization-defined frequency] to verify media reliability and information integrity.', 'kb-doc-14-nist-sp-800-53-p153-5', 0, 24, '14-nist-sp-800-53', 'retrieved', '64628606EE6157524393BCAF841BCB0591B9225AE36FB76F583CD0F07E0D50E6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p153-6', 'doc-14-nist-sp-800-53', '', 153, 'Discussion: Organizations need assurance that backup information can be reliably retrieved.', 'kb-doc-14-nist-sp-800-53-p153-6', 0, 11, '14-nist-sp-800-53', 'retrieved', '596233225B9CC3C83424738149B2329C1A041208008FEBDB84167FDBC750FBD8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p153-7', 'doc-14-nist-sp-800-53', '', 153, 'Reliability pertains to the systems and system components where the backup information is stored, the operations used to retrieve the information, and the integrity of the information being retrieved. Independent and specialized tests can be used for each of the aspects of reliability. For example, decrypting and transporting (or transmitting) a random sample of backup files from the alternate storage or backup site and comparing the information to the same information at the primary processing site can provide such assurance.', 'kb-doc-14-nist-sp-800-53-p153-7', 0, 80, '14-nist-sp-800-53', 'retrieved', '9713BE9908B9D4432D9DB3D100916D183D3C14965FD902B55367472F7EA927AA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p153-9', 'doc-14-nist-sp-800-53', '', 153, '(2) SYSTEM BACKUP | TEST RESTORATION USING SAMPLING Use a sample of backup information in the restoration of selected system functions as part of contingency plan testing.', 'kb-doc-14-nist-sp-800-53-p153-9', 0, 27, '14-nist-sp-800-53', 'retrieved', 'FB12DCB81E98C1E4DCB30EF541448BC2BECB1034EDB0AC447FDB28C526DDF370', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p153-10', 'doc-14-nist-sp-800-53', '', 153, 'Discussion: Organizations need assurance that system functions can be restored correctly and can support established organizational missions. To ensure that the selected system functions are thoroughly exercised during contingency plan testing, a sample of backup information is retrieved to determine whether the functions are operating as intended.', 'kb-doc-14-nist-sp-800-53-p153-10', 0, 47, '14-nist-sp-800-53', 'retrieved', '1A3932331B46820FF7BC5871E086E02B1F0BA039C50778380800FB2CDB5401C4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p153-11', 'doc-14-nist-sp-800-53', '', 153, 'Organizations can determine the sample size for the functions and backup information based on the level of assurance needed.', 'kb-doc-14-nist-sp-800-53-p153-11', 0, 19, '14-nist-sp-800-53', 'retrieved', 'D7C549B6120EFB7FA41BD7DA7A7265BFDAFFE7A67DCC2179226AAF6B38BC4F70', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p153-13', 'doc-14-nist-sp-800-53', '', 153, '(3) SYSTEM BACKUP | SEPARATE STORAGE FOR CRITICAL INFORMATION Store backup copies of [Assignment: organization-defined critical system software and other security-related information] in a separate facility or in a fire rated container that is not collocated with the operational system.', 'kb-doc-14-nist-sp-800-53-p153-13', 0, 40, '14-nist-sp-800-53', 'retrieved', '52FC0C1CE8D546BA4030A455A5C8B3882864A8F40B3AAE85CC33D1029D21006E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p153-14', 'doc-14-nist-sp-800-53', '', 153, 'Discussion: Separate storage for critical information applies to all critical information regardless of the type of backup storage media. Critical system software includes operating systems, middleware, cryptographic key management systems, and intrusion detection systems. Security-related information includes inventories of system hardware, software, and firmware components. Alternate storage sites, including geographically distributed architectures, serve as separate storage facilities for organizations. Organizations may', 'kb-doc-14-nist-sp-800-53-p153-14', 0, 61, '14-nist-sp-800-53', 'retrieved', 'C1CBFA1B7F816013E2F738F70FCEA2F414E1F555840CFB3D624FD717D207A4AC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
