VALUES ('doc-14-nist-sp-800-53-p154-1', 'doc-14-nist-sp-800-53', '', 154, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 127 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p154-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'C2FE030BA2FDFBD168C73E8B1D59315975A03ABF23C3EB4BB33AAE3B8C75D7A8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
