INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p154-2', 'doc-14-nist-sp-800-53', '', 154, 'provide separate storage by implementing automated backup processes at alternative storage sites (e.g., data centers). The General Services Administration (GSA) establishes standards and specifications for security and fire rated containers.', 'kb-doc-14-nist-sp-800-53-p154-2', 0, 30, '14-nist-sp-800-53', 'retrieved', 'EE38A0D917770D1CBD6BA273DD2D3F44948F6CA4FBCC6AC5B9397277737DF9F5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
