INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p154-4', 'doc-14-nist-sp-800-53', '', 154, '(4) SYSTEM BACKUP | PROTECTION FROM UNAUTHORIZED MODIFICATION [Withdrawn: Incorporated into CP-9.] (5) SYSTEM BACKUP | TRANSFER TO ALTERNATE STORAGE SITE Transfer system backup information to the alternate storage site [Assignment: organization-defined time period and transfer rate consistent with the recovery time and recovery point objectives].', 'kb-doc-14-nist-sp-800-53-p154-4', 0, 46, '14-nist-sp-800-53', 'retrieved', 'D20DB481FADE756B00F40380C9D4258A73ACB91EE5508CD33DB6575FE75645FA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
