INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p154-5', 'doc-14-nist-sp-800-53', '', 154, 'Discussion: System backup information can be transferred to alternate storage sites either electronically or by the physical shipment of storage media.', 'kb-doc-14-nist-sp-800-53-p154-5', 0, 21, '14-nist-sp-800-53', 'retrieved', '532A0F5ED44B060F0405E5B1E323EDE211099FBE082B246CDE9C9E5C63932FC1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
