INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p154-7', 'doc-14-nist-sp-800-53', '', 154, '(6) SYSTEM BACKUP | REDUNDANT SECONDARY SYSTEM Conduct system backup by maintaining a redundant secondary system that is not collocated with the primary system and that can be activated without loss of information or disruption to operations.', 'kb-doc-14-nist-sp-800-53-p154-7', 0, 37, '14-nist-sp-800-53', 'retrieved', '36713314ABA77A94A665401361B88391D89141E31ADDB44B9E306980CE603C44', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
