INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p155-2', 'doc-14-nist-sp-800-53', '', 155, 'CP-10 SYSTEM RECOVERY AND RECONSTITUTION Control: Provide for the recovery and reconstitution of the system to a known state within [Assignment: organization-defined time period consistent with recovery time and recovery point objectives] after a disruption, compromise, or failure.', 'kb-doc-14-nist-sp-800-53-p155-2', 0, 38, '14-nist-sp-800-53', 'retrieved', '6026C2F679681D899F469841592A2EF43172C1F395BF29AE87313AD39445D81D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p155-3', 'doc-14-nist-sp-800-53', '', 155, 'Discussion: Recovery is executing contingency plan activities to restore organizational mission and business functions. Reconstitution takes place following recovery and includes activities for returning systems to fully operational states. Recovery and reconstitution operations reflect mission and business priorities; recovery point, recovery time, and reconstitution objectives; and organizational metrics consistent with contingency plan requirements. Reconstitution includes the deactivation of interim system capabilities that may have been needed during recovery operations. Reconstitution also includes assessments of fully restored system capabilities, reestablishment of continuous monitoring activities, system reauthorization (if required), and activities to prepare the system and organization for future disruptions, breaches, compromises, or failures. Recovery and reconstitution capabilities can include automated mechanisms and manual procedures.', 'kb-doc-14-nist-sp-800-53-p155-3', 0, 113, '14-nist-sp-800-53', 'retrieved', '2274BD745139FDDA3A1DFE18255453EAE0841FA87125D2421EFBD1948160A2E1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p155-4', 'doc-14-nist-sp-800-53', '', 155, 'Organizations establish recovery time and recovery point objectives as part of contingency planning.', 'kb-doc-14-nist-sp-800-53-p155-4', 0, 13, '14-nist-sp-800-53', 'retrieved', '038E2945C51F67C65AAE8689E062D521A0450A4F4B037E95D00EC547886B7273', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p155-6', 'doc-14-nist-sp-800-53', '', 155, 'Control Enhancements: (1) SYSTEM RECOVERY AND RECONSTITUTION | CONTINGENCY PLAN TESTING [Withdrawn: Incorporated into CP-4.] (2) SYSTEM RECOVERY AND RECONSTITUTION | TRANSACTION RECOVERY Implement transaction recovery for systems that are transaction-based.', 'kb-doc-14-nist-sp-800-53-p155-6', 0, 31, '14-nist-sp-800-53', 'retrieved', '9789A3EF0A61AAE44B91878DA37A123DF2616BA847A97AE287A594A849438022', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p155-7', 'doc-14-nist-sp-800-53', '', 155, 'Discussion: Transaction-based systems include database management systems and transaction processing systems. Mechanisms supporting transaction recovery include transaction rollback and transaction journaling.', 'kb-doc-14-nist-sp-800-53-p155-7', 0, 21, '14-nist-sp-800-53', 'retrieved', 'B24F77D003EFB7DA35FBD1B6740ADBFF85FE61487E0FF449AB2905AE8E24C549', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p155-9', 'doc-14-nist-sp-800-53', '', 155, '(3) SYSTEM RECOVERY AND RECONSTITUTION | COMPENSATING SECURITY CONTROLS [Withdrawn: Addressed through tailoring.] (4) SYSTEM RECOVERY AND RECONSTITUTION | RESTORE WITHIN TIME PERIOD Provide the capability to restore system components within [Assignment: organization- defined restoration time periods] from configuration-controlled and integrity-protected information representing a known, operational state for the components.', 'kb-doc-14-nist-sp-800-53-p155-9', 0, 50, '14-nist-sp-800-53', 'retrieved', 'FD7EC4A4AF08502637A4DFA88DB03BEA1B9393DB29D8A3B0CB19BD7D9EAD6DA0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p155-10', 'doc-14-nist-sp-800-53', '', 155, 'Discussion: Restoration of system components includes reimaging, which restores the components to known, operational states.', 'kb-doc-14-nist-sp-800-53-p155-10', 0, 15, '14-nist-sp-800-53', 'retrieved', 'D040DA3F74E3249C6532889F84157ED678004BD2AD7F92461080690CDABD99CE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
