INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p155-12', 'doc-14-nist-sp-800-53', '', 155, '(5) SYSTEM RECOVERY AND RECONSTITUTION | FAILOVER CAPABILITY [Withdrawn: Incorporated into SI-13.] (6) SYSTEM RECOVERY AND RECONSTITUTION | COMPONENT PROTECTION Protect system components used for recovery and reconstitution.', 'kb-doc-14-nist-sp-800-53-p155-12', 0, 28, '14-nist-sp-800-53', 'retrieved', '8D8C850FE8FD4FA652EC0D1B4961FAE7C1E6DD95FD34B4262AD140DEB7F8B2CE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
