INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p155-13', 'doc-14-nist-sp-800-53', '', 155, 'Discussion: Protection of system recovery and reconstitution components (i.e., hardware, firmware, and software) includes physical and technical controls. Backup and restoration components used for recovery and reconstitution include router tables, compilers, and other system software.', 'kb-doc-14-nist-sp-800-53-p155-13', 0, 35, '14-nist-sp-800-53', 'retrieved', 'E13759D764B6E017C66FD4FD98E58A4CF9F7D4B45C034E18B219772AAF17D9A4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
