VALUES ('doc-14-nist-sp-800-53-p156-1', 'doc-14-nist-sp-800-53', '', 156, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 129 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p156-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '0820ED5081DFDD927DD176EE58730761D056E8BC2A0E0CAC4043202B9E99AE66', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
