INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p156-3', 'doc-14-nist-sp-800-53', '', 156, 'CP-11 ALTERNATE COMMUNICATIONS PROTOCOLS Control: Provide the capability to employ [Assignment: organization-defined alternative communications protocols] in support of maintaining continuity of operations.', 'kb-doc-14-nist-sp-800-53-p156-3', 0, 22, '14-nist-sp-800-53', 'retrieved', '28411D7696EABB5E8EA6FA62D88574410645B0F7674869FBF4608E9B320C0C9B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p156-4', 'doc-14-nist-sp-800-53', '', 156, 'Discussion: Contingency plans and the contingency training or testing associated with those plans incorporate an alternate communications protocol capability as part of establishing resilience in organizational systems. Switching communications protocols may affect software applications and operational aspects of systems. Organizations assess the potential side effects of introducing alternate communications protocols prior to implementation.', 'kb-doc-14-nist-sp-800-53-p156-4', 0, 53, '14-nist-sp-800-53', 'retrieved', '548E5F185333C1399F3E4A29D2B903B876B01CE8FF2160381C0EA74BD91A5EDC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p156-8', 'doc-14-nist-sp-800-53', '', 156, 'CP-12 SAFE MODE Control: When [Assignment: organization-defined conditions] are detected, enter a safe mode of operation with [Assignment: organization-defined restrictions of safe mode of operation].', 'kb-doc-14-nist-sp-800-53-p156-8', 0, 25, '14-nist-sp-800-53', 'retrieved', '8E264B938E0EDC437E7A60CFB41CEF3F831B7FF65387BDE1D134FE43312D52E4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p156-9', 'doc-14-nist-sp-800-53', '', 156, 'Discussion: For systems that support critical mission and business functions— including military operations, civilian space operations, nuclear power plant operations, and air traffic control operations (especially real-time operational environments)— organizations can identify certain conditions under which those systems revert to a predefined safe mode of operation. The safe mode of operation, which can be activated either automatically or manually, restricts the operations that systems can execute when those conditions are encountered. Restriction includes allowing only selected functions to execute that can be carried out under limited power or with reduced communications bandwidth.', 'kb-doc-14-nist-sp-800-53-p156-9', 0, 92, '14-nist-sp-800-53', 'retrieved', '58B247248667B7A2B0AEB09096110990F49858107866E905EAE107D16D1806F1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p156-13', 'doc-14-nist-sp-800-53', '', 156, 'CP-13 ALTERNATIVE SECURITY MECHANISMS Control: Employ [Assignment: organization-defined alternative or supplemental security mechanisms] for satisfying [Assignment: organization-defined security functions] when the primary means of implementing the security function is unavailable or compromised.', 'kb-doc-14-nist-sp-800-53-p156-13', 0, 32, '14-nist-sp-800-53', 'retrieved', 'F7EACCE3BA89623B73E4FDAB4A72F421E9B2BCC88152EB79D048EC0A52C8A5CD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
