VALUES ('doc-14-nist-sp-800-53-p158-1', 'doc-14-nist-sp-800-53', '', 158, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 131 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p158-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'C3C62786B3E616D39212FB6DBFF456D021856C12722B85854BB6024C82C2A573', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
