INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p159-6', 'doc-14-nist-sp-800-53', '', 159, 'Related Controls: AC-2, AC-3, AC-4, AC-14, AC-17, AC-18, AU-1, AU-6, IA-4, IA-5, IA-8, MA-4, MA- 5, PE-2, PL-4, SA-4, SA-8.', 'kb-doc-14-nist-sp-800-53-p159-6', 0, 20, '14-nist-sp-800-53', 'retrieved', '4AEA595063004ABBEAD65C89DB27C9AF1CF28BE91CD6A33C7A4A1F75CE35DDF3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
