VALUES ('doc-14-nist-sp-800-53-p160-4', 'doc-14-nist-sp-800-53', '', 160, 'Multi-factor authentication solutions that feature physical authenticators include hardware authenticators that provide time-based or challenge-response outputs and smart cards such as the U.S. Government Personal Identity Verification card or the DoD Common Access Card.', 'kb-doc-14-nist-sp-800-53-p160-4', 0, 34, '14-nist-sp-800-53', 'retrieved', 'D57872C1AFC088FA4390C675992FF62A12D9392E5D82452B1861ABCB01AC74B2', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
