INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p160-5', 'doc-14-nist-sp-800-53', '', 160, 'In addition to authenticating users at the system level, organizations may also employ authentication mechanisms at the application level, at their discretion, to provide increased information security. Regardless of the type of access (i.e., local, network, remote), non- privileged accounts are authenticated using multi-factor options appropriate for the level of risk. Organizations can provide additional security measures, such as additional or more rigorous authentication mechanisms, for specific types of access.', 'kb-doc-14-nist-sp-800-53-p160-5', 0, 70, '14-nist-sp-800-53', 'retrieved', '1E633774298BE1CD5C2F3D9ACA88DFA0F2AAF4F28A40E4AFE4B4FC41728A9446', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
