INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p160-7', 'doc-14-nist-sp-800-53', '', 160, '(3) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | LOCAL ACCESS TO PRIVILEGED ACCOUNTS [Withdrawn: Incorporated into IA-2(1).] (4) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | LOCAL ACCESS TO NON- PRIVILEGED ACCOUNTS [Withdrawn: Incorporated into IA-2(2).] (5) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | INDIVIDUAL AUTHENTICATION WITH GROUP AUTHENTICATION When shared accounts or authenticators are employed, require users to be individually authenticated before granting access to the shared accounts or resources.', 'kb-doc-14-nist-sp-800-53-p160-7', 0, 67, '14-nist-sp-800-53', 'retrieved', '65D6C42734C2FADBA0631A1AB7705149171168042AA44AC5132DA4EA93C8E935', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
