INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p160-8', 'doc-14-nist-sp-800-53', '', 160, 'Discussion: Individual authentication prior to shared group authentication mitigates the risk of using group accounts or authenticators.', 'kb-doc-14-nist-sp-800-53-p160-8', 0, 17, '14-nist-sp-800-53', 'retrieved', '3EEB883B5C6F571DB8ED91E66C9D596CFEF6FCADE39B79672C4181554D198A4E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
