INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p161-2', 'doc-14-nist-sp-800-53', '', 161, '(7) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | NETWORK ACCESS TO NON- PRIVILEGED ACCOUNTS — SEPARATE DEVICE [Withdrawn: Incorporated into IA-2(6).] (8) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | ACCESS TO ACCOUNTS — REPLAY RESISTANT Implement replay-resistant authentication mechanisms for access to [Selection (one or more): privileged accounts; non-privileged accounts].', 'kb-doc-14-nist-sp-800-53-p161-2', 0, 48, '14-nist-sp-800-53', 'retrieved', '166C6508B646F40A7648ABC63B3073DA218B72095C67E540E832DD8E3B445538', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
