INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p161-3', 'doc-14-nist-sp-800-53', '', 161, 'Discussion: Authentication processes resist replay attacks if it is impractical to achieve successful authentications by replaying previous authentication messages. Replay-resistant techniques include protocols that use nonces or challenges such as time synchronous or cryptographic authenticators.', 'kb-doc-14-nist-sp-800-53-p161-3', 0, 35, '14-nist-sp-800-53', 'retrieved', 'B2B138DD44002F6EE0242CF53FE5B560F2944C27CA76889742452B9AFC04A81A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
