INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p161-5', 'doc-14-nist-sp-800-53', '', 161, '(9) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | NETWORK ACCESS TO NON- PRIVILEGED ACCOUNTS — REPLAY RESISTANT [Withdrawn: Incorporated into IA-2(8).] (10) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | SINGLE SIGN-ON Provide a single sign-on capability for [Assignment: organization-defined system accounts and services].', 'kb-doc-14-nist-sp-800-53-p161-5', 0, 41, '14-nist-sp-800-53', 'retrieved', '44AA3A8C078C35E9E63FB1A5C8F6A7C360071C1E703839F30093C321D9B04952', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p161-6', 'doc-14-nist-sp-800-53', '', 161, 'Discussion: Single sign-on enables users to log in once and gain access to multiple system resources. Organizations consider the operational efficiencies provided by single sign-on capabilities with the risk introduced by allowing access to multiple systems via a single authentication event. Single sign-on can present opportunities to improve system security, for example by providing the ability to add multi-factor authentication for applications and systems (existing and new) that may not be able to natively support multi-factor authentication.', 'kb-doc-14-nist-sp-800-53-p161-6', 0, 77, '14-nist-sp-800-53', 'retrieved', 'BE7B30618B279435C95DD9E9479BB48378C3F0BED47B89ED6700AEE498FDE96E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p161-8', 'doc-14-nist-sp-800-53', '', 161, '(11) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | REMOTE ACCESS — SEPARATE DEVICE [Withdrawn: Incorporated into IA-2(6).] (12) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | ACCEPTANCE OF PIV CREDENTIALS Accept and electronically verify Personal Identity Verification-compliant credentials.', 'kb-doc-14-nist-sp-800-53-p161-8', 0, 35, '14-nist-sp-800-53', 'retrieved', '736517EFE344E434C1015415CA0CF85E6B8A07FC8D30D08D58087AD480CA5A03', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
