INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p161-12', 'doc-14-nist-sp-800-53', '', 161, '(13) IDENTIFICATION AND AUTHENTICATION (ORGANIZATIONAL USERS) | OUT-OF-BAND AUTHENTICATION Implement the following out-of-band authentication mechanisms under [Assignment: organization-defined conditions]: [Assignment: organization-defined out-of-band authentication].', 'kb-doc-14-nist-sp-800-53-p161-12', 0, 23, '14-nist-sp-800-53', 'retrieved', '7DC17F304AF8312BFC6BB88D3002E3D57FE0C385CDB3628C4D853E44934D6DF9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
