INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p162-8', 'doc-14-nist-sp-800-53', '', 162, 'Control Enhancements: (1) DEVICE IDENTIFICATION AND AUTHENTICATION | CRYPTOGRAPHIC BIDIRECTIONAL AUTHENTICATION Authenticate [Assignment: organization-defined devices and/or types of devices] before establishing [Selection (one or more): local; remote; network] connection using bidirectional authentication that is cryptographically based.', 'kb-doc-14-nist-sp-800-53-p162-8', 0, 36, '14-nist-sp-800-53', 'retrieved', '5245AED3435289BA9093EA708AAFBDAF39824A1E755DD437CFB41786CB4BCD7B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
