INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p162-9', 'doc-14-nist-sp-800-53', '', 162, 'Discussion: A local connection is a connection with a device that communicates without the use of a network. A network connection is a connection with a device that communicates through a network. A remote connection is a connection with a device that communicates through an external network. Bidirectional authentication provides stronger protection to validate the identity of other devices for connections that are of greater risk.', 'kb-doc-14-nist-sp-800-53-p162-9', 0, 66, '14-nist-sp-800-53', 'retrieved', 'A12856FB7D8837D923A1034A8F7A0AE6253030795889644F0B8E66EBEAE0472D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
