VALUES ('doc-14-nist-sp-800-53-p162-11', 'doc-14-nist-sp-800-53', '', 162, '(2) DEVICE IDENTIFICATION AND AUTHENTICATION | CRYPTOGRAPHIC BIDIRECTIONAL NETWORK AUTHENTICATION', 'kb-doc-14-nist-sp-800-53-p162-11', 0, 10, '14-nist-sp-800-53', 'retrieved', '50540B7840AB96F39405EF7412DC5DD67A917148C700BCB7C4DC3FEF42E25628', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
