INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p163-2', 'doc-14-nist-sp-800-53', '', 163, '[Withdrawn: Incorporated into IA-3(1).] (3) DEVICE IDENTIFICATION AND AUTHENTICATION | DYNAMIC ADDRESS ALLOCATION (a) Where addresses are allocated dynamically, standardize dynamic address allocation lease information and the lease duration assigned to devices in accordance with [Assignment: organization-defined lease information and lease duration]; and (b) Audit lease information when assigned to a device.', 'kb-doc-14-nist-sp-800-53-p163-2', 0, 52, '14-nist-sp-800-53', 'retrieved', '6BF2CA0080E42B5E1918122A278732021F9697B9652DE0CA20DC98D0DF19CECC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
