INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p163-3', 'doc-14-nist-sp-800-53', '', 163, 'Discussion: The Dynamic Host Configuration Protocol (DHCP) is an example of a means by which clients can dynamically receive network address assignments.', 'kb-doc-14-nist-sp-800-53-p163-3', 0, 22, '14-nist-sp-800-53', 'retrieved', '2EA5683D60847F5CE8DD2CA603AAC98E45AAD889895E62E33575842F95FD109E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
