INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p163-12', 'doc-14-nist-sp-800-53', '', 163, 'Control Enhancements: (1) IDENTIFIER MANAGEMENT | PROHIBIT ACCOUNT IDENTIFIERS AS PUBLIC IDENTIFIERS Prohibit the use of system account identifiers that are the same as public identifiers for individual accounts.', 'kb-doc-14-nist-sp-800-53-p163-12', 0, 29, '14-nist-sp-800-53', 'retrieved', '55ACBAFCE68968B26DDEEC9705C480BBCF2947E7BB007F3EA6708BB3159038A9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p163-13', 'doc-14-nist-sp-800-53', '', 163, 'Discussion: Prohibiting account identifiers as public identifiers applies to any publicly disclosed account identifier used for communication such as, electronic mail and instant', 'kb-doc-14-nist-sp-800-53-p163-13', 0, 23, '14-nist-sp-800-53', 'retrieved', '45FF553E339DCBB3C468AD394023FBD6B7562C9DB9DEB800D5F212D853DDA73B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
