INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p164-11', 'doc-14-nist-sp-800-53', '', 164, 'Discussion: Cross-organization identifier management provides the capability to identify individuals, groups, roles, or devices when conducting cross-organization activities involving the processing, storage, or transmission of information.', 'kb-doc-14-nist-sp-800-53-p164-11', 0, 26, '14-nist-sp-800-53', 'retrieved', 'F98164B4E034761DDE7925ADE785BFB15E3EB5107D44850282BF1037B21A5F08', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
