INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p164-13', 'doc-14-nist-sp-800-53', '', 164, '(7) IDENTIFIER MANAGEMENT | IN-PERSON REGISTRATION [Withdrawn: Incorporated into IA-12(4).] (8) IDENTIFIER MANAGEMENT | PAIRWISE PSEUDONYMOUS IDENTIFIERS Generate pairwise pseudonymous identifiers.', 'kb-doc-14-nist-sp-800-53-p164-13', 0, 21, '14-nist-sp-800-53', 'retrieved', 'B72529A4003EB722E4AC921B9898630446B9C3B540DA574B91BFF21652C00870', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
