INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p164-14', 'doc-14-nist-sp-800-53', '', 164, 'Discussion: A pairwise pseudonymous identifier is an opaque unguessable subscriber identifier generated by an identity provider for use at a specific individual relying party.', 'kb-doc-14-nist-sp-800-53-p164-14', 0, 24, '14-nist-sp-800-53', 'retrieved', '726D22AC6C490928ABC518E325A49ACDA06B04C6575512A99C5651F842A01DD6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p164-15', 'doc-14-nist-sp-800-53', '', 164, 'Generating distinct pairwise pseudonymous identifiers with no identifying information about a subscriber discourages subscriber activity tracking and profiling beyond the operational', 'kb-doc-14-nist-sp-800-53-p164-15', 0, 21, '14-nist-sp-800-53', 'retrieved', '409AE12744F7534BD792845E7A6002A569805D36BC70639F5C532C8FAA3AC57F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
