VALUES ('doc-14-nist-sp-800-53-p165-1', 'doc-14-nist-sp-800-53', '', 165, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 138 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p165-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'B147A1A285D04743861BB78B3B8CBF3728A7661AD095D3CA17FDD94AE1E9E3BA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p165-2', 'doc-14-nist-sp-800-53', '', 165, 'requirements established by an organization. The pairwise pseudonymous identifiers are unique to each relying party except in situations where relying parties can show a demonstrable relationship justifying an operational need for correlation, or all parties consent to being correlated in such a manner.', 'kb-doc-14-nist-sp-800-53-p165-2', 0, 43, '14-nist-sp-800-53', 'retrieved', 'E54DAFEDF76165317DA075F0B06E0C995A599C57D4C4B876E0FBCB2A509B4E29', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
