INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p165-5', 'doc-14-nist-sp-800-53', '', 165, 'Discussion: For each of the entities covered in IA-2, IA-3, IA-8, and IA-9 , it is important to maintain the attributes for each authenticated entity on an ongoing basis in a central (protected) store.', 'kb-doc-14-nist-sp-800-53-p165-5', 0, 34, '14-nist-sp-800-53', 'retrieved', '527B2CB2BC1DEDF80C6D0876136599D6235EE491D20AB8ECED01911262AA8F10', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
