VALUES ('doc-14-nist-sp-800-53-p165-7', 'doc-14-nist-sp-800-53', '', 165, 'References: [FIPS 201-2], [SP 800-63-3], [SP 800-73-4], [SP 800-76-2], [SP 800-78-4].', 'kb-doc-14-nist-sp-800-53-p165-7', 0, 11, '14-nist-sp-800-53', 'retrieved', '4EF96E9C37A15A491A278D6F3B18A47D8F601B8BDA8BB7F949DD3751C1954A98', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
