INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p168-5', 'doc-14-nist-sp-800-53', '', 168, 'Discussion: Federation provides organizations with the capability to authenticate individuals and devices when conducting cross-organization activities involving the processing, storage, or transmission of information. Using a specific list of approved external organizations for authentication helps to ensure that those organizations are vetted and trusted.', 'kb-doc-14-nist-sp-800-53-p168-5', 0, 44, '14-nist-sp-800-53', 'retrieved', 'CA717225CECC61905A9D58FC1B897203840DEAB72A0D00E8F61A4687C1D6012C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
