VALUES ('doc-14-nist-sp-800-53-p169-1', 'doc-14-nist-sp-800-53', '', 169, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 142 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p169-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'CF12813A854B89AFEA8F4A953BEFFFF2E6D77E65C5753DA1611124B2A987E91C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
