INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p169-2', 'doc-14-nist-sp-800-53', '', 169, '(13) AUTHENTICATOR MANAGEMENT | EXPIRATION OF CACHED AUTHENTICATORS Prohibit the use of cached authenticators after [Assignment: organization-defined time period].', 'kb-doc-14-nist-sp-800-53-p169-2', 0, 19, '14-nist-sp-800-53', 'retrieved', 'F60C4AB49C0CF1AE902CEE827D540C370FE0F8CEB2A2D656769B49B10D5FA09E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
