INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p169-3', 'doc-14-nist-sp-800-53', '', 169, 'Discussion: Cached authenticators are used to authenticate to the local machine when the network is not available. If cached authentication information is out of date, the validity of the authentication information may be questionable.', 'kb-doc-14-nist-sp-800-53-p169-3', 0, 34, '14-nist-sp-800-53', 'retrieved', 'AA55736481F3206BE79A50BC4CA8E2AADE2F284FD22AB947641A9FB16E716277', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
