INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p169-5', 'doc-14-nist-sp-800-53', '', 169, '(14) AUTHENTICATOR MANAGEMENT | MANAGING CONTENT OF PKI TRUST STORES For PKI-based authentication, employ an organization-wide methodology for managing the content of PKI trust stores installed across all platforms, including networks, operating systems, browsers, and applications.', 'kb-doc-14-nist-sp-800-53-p169-5', 0, 36, '14-nist-sp-800-53', 'retrieved', 'E9663D034C23E952B28D2BA28B958B84D1BABA2379BC316AD0EF8E1AEBDA2A38', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
