INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p169-6', 'doc-14-nist-sp-800-53', '', 169, 'Discussion: An organization-wide methodology for managing the content of PKI trust stores helps improve the accuracy and currency of PKI-based authentication credentials across the organization.', 'kb-doc-14-nist-sp-800-53-p169-6', 0, 25, '14-nist-sp-800-53', 'retrieved', '83947A45C43BF0F80CC0FA85F2124DD7A3A5232D7BB6EBF1AB027965C131EFA8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
