INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p169-8', 'doc-14-nist-sp-800-53', '', 169, '(15) AUTHENTICATOR MANAGEMENT | GSA-APPROVED PRODUCTS AND SERVICES Use only General Services Administration-approved products and services for identity, credential, and access management.', 'kb-doc-14-nist-sp-800-53-p169-8', 0, 22, '14-nist-sp-800-53', 'retrieved', '551B314D92BAB72A7162A2498EAC688D987BC29ADB70AEE8292FF474EB14A7CD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
