INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p169-12', 'doc-14-nist-sp-800-53', '', 169, 'Discussion: Issuing authenticators in person or by a trusted external party enhances and reinforces the trustworthiness of the identity proofing process.', 'kb-doc-14-nist-sp-800-53-p169-12', 0, 21, '14-nist-sp-800-53', 'retrieved', '02FDDE943D56C17A7B0CE6AF96D3DCCED9961CB965CECB1D527F5518085CAD60', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
