INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p170-16', 'doc-14-nist-sp-800-53', '', 170, 'IA-8 IDENTIFICATION AND AUTHENTICATION (NON-ORGANIZATIONAL USERS) Control: Uniquely identify and authenticate non-organizational users or processes acting on behalf of non-organizational users.', 'kb-doc-14-nist-sp-800-53-p170-16', 0, 21, '14-nist-sp-800-53', 'retrieved', 'A19B87A0E5F6E52C5AA0D37CE6C9EB5BEBAD8C2234A6B301C4D5A1FC7AD918FA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
