INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p171-3', 'doc-14-nist-sp-800-53', '', 171, 'Related Controls: AC-2, AC-6, AC-14, AC-17, AC-18, AU-6, IA-2, IA-4, IA-5, IA-10, IA-11, MA-4, RA- 3, SA-4, SC-8.', 'kb-doc-14-nist-sp-800-53-p171-3', 0, 18, '14-nist-sp-800-53', 'retrieved', '5D91C18026B0ACCF5A386B34945EF8346B7384CF441F4E22A15AF272388A0BD9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
