VALUES ('doc-14-nist-sp-800-53-p173-1', 'doc-14-nist-sp-800-53', '', 173, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 146 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p173-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'EB62DFBA4E935E9A9CA3BBDB36C0F79E90240255BB98B75F0B386301BABF8FED', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
