VALUES ('doc-14-nist-sp-800-53-p173-2', 'doc-14-nist-sp-800-53', '', 173, '(2) SERVICE IDENTIFICATION AND AUTHENTICATION | TRANSMISSION OF DECISIONS [Withdrawn: Incorporated into IA-9.] References: None.', 'kb-doc-14-nist-sp-800-53-p173-2', 0, 15, '14-nist-sp-800-53', 'retrieved', 'BCF2EDC8DB08B221D59CE9FCD1EFBA2A141087BF85B3AFA80F2027E7BE9C957E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
