VALUES ('doc-14-nist-sp-800-53-p175-1', 'doc-14-nist-sp-800-53', '', 175, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 148 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p175-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '939CD1803E3A1C5C9C4060C07F599B29A30128707F52B914802A9C4BCB7F6478', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
