VALUES ('doc-14-nist-sp-800-53-p177-1', 'doc-14-nist-sp-800-53', '', 177, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 150 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p177-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'D9275E62F492317E89E71A31EEE4303DCCE4BA35816324FBC0F634830BC19F6B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
