INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p177-9', 'doc-14-nist-sp-800-53', '', 177, '(2) INCIDENT RESPONSE TRAINING | AUTOMATED TRAINING ENVIRONMENTS Provide an incident response training environment using [Assignment: organization- defined automated mechanisms].', 'kb-doc-14-nist-sp-800-53-p177-9', 0, 20, '14-nist-sp-800-53', 'retrieved', '77D9515CE081329B678EFB294BEE80E79D413FB1A167C1F162395CC924E6B64E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p177-10', 'doc-14-nist-sp-800-53', '', 177, 'Discussion: Automated mechanisms can provide a more thorough and realistic incident response training environment. This can be accomplished, for example, by providing more complete coverage of incident response issues, selecting more realistic training scenarios and environments, and stressing the response capability.', 'kb-doc-14-nist-sp-800-53-p177-10', 0, 41, '14-nist-sp-800-53', 'retrieved', '39975C4452933E250D9FC9978FAB85E426198F11BF106F68F9E1CE25F36530EB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p177-12', 'doc-14-nist-sp-800-53', '', 177, '(3) INCIDENT RESPONSE TRAINING | BREACH Provide incident response training on how to identify and respond to a breach, including the organization’s process for reporting a breach.', 'kb-doc-14-nist-sp-800-53-p177-12', 0, 27, '14-nist-sp-800-53', 'retrieved', '08489998C889297C0FD8202B51171875D1F8871ABD47843C1DE85315D4C9B757', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
