INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p178-9', 'doc-14-nist-sp-800-53', '', 178, 'Discussion: Organizations use automated mechanisms to more thoroughly and effectively test incident response capabilities. This can be accomplished by providing more complete coverage of incident response issues, selecting realistic test scenarios and environments, and stressing the response capability.', 'kb-doc-14-nist-sp-800-53-p178-9', 0, 38, '14-nist-sp-800-53', 'retrieved', '627273C87BD2952392CCD04FBB8EDED1439707B3DB83B270BB0955E9394CF0FE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
