INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p178-11', 'doc-14-nist-sp-800-53', '', 178, '(2) INCIDENT RESPONSE TESTING | COORDINATION WITH RELATED PLANS Coordinate incident response testing with organizational elements responsible for related plans.', 'kb-doc-14-nist-sp-800-53-p178-11', 0, 20, '14-nist-sp-800-53', 'retrieved', '2DDB60DEBFF25F4D488BC73BC8116986DF72C960C130164DDA4C8A01D259E009', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
