INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p178-12', 'doc-14-nist-sp-800-53', '', 178, 'Discussion: Organizational plans related to incident response testing include business continuity plans, disaster recovery plans, continuity of operations plans, contingency plans, crisis communications plans, critical infrastructure plans, and occupant emergency plans.', 'kb-doc-14-nist-sp-800-53-p178-12', 0, 31, '14-nist-sp-800-53', 'retrieved', 'D80B1BE064B4B00B677CF97D8110B4F976163002D42416EA844492F785E9DDE2', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
