INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p178-14', 'doc-14-nist-sp-800-53', '', 178, '(3) INCIDENT RESPONSE TESTING | CONTINUOUS IMPROVEMENT Use qualitative and quantitative data from testing to: (a) Determine the effectiveness of incident response processes; (b) Continuously improve incident response processes; and (c) Provide incident response measures and metrics that are accurate, consistent, and in a reproducible format.', 'kb-doc-14-nist-sp-800-53-p178-14', 0, 46, '14-nist-sp-800-53', 'retrieved', '89D5D87D5F9709F46B9DD45F492C671E3FD540EB9ED9768752E671ED49D535EC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
