VALUES ('doc-14-nist-sp-800-53-p179-7', 'doc-14-nist-sp-800-53', '', 179, 'Related Controls: AC-19, AU-6, AU-7, CM-6, CP-2, CP-3, CP-4, IR-2, IR-3, IR-5, IR-6, IR-8, PE-6, PL- 2, PM-12, SA-8, SC-5, SC-7, SI-3, SI-4, SI-7.', 'kb-doc-14-nist-sp-800-53-p179-7', 0, 24, '14-nist-sp-800-53', 'retrieved', 'DE0EC3DAAC6D6871BB443E5B4C50F03AC3491707EB3E6C1311F01DFB1F49ED5E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
