INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p179-9', 'doc-14-nist-sp-800-53', '', 179, 'Discussion: Automated mechanisms that support incident handling processes include online incident management systems and tools that support the collection of live response data, full network packet capture, and forensic analysis.', 'kb-doc-14-nist-sp-800-53-p179-9', 0, 30, '14-nist-sp-800-53', 'retrieved', 'E89ADD951B7C8BDAF8F86FE98D5DEB0D5E893C51C7215A246634C96058C1B68A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
