VALUES ('doc-14-nist-sp-800-53-p180-1', 'doc-14-nist-sp-800-53', '', 180, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 153 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p180-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'F75F335B1D76C47F61065211E9A619419642F377B582EC348B5741E1D6AA987A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
