INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p180-2', 'doc-14-nist-sp-800-53', '', 180, 'Include the following types of dynamic reconfiguration for [Assignment: organization- defined system components] as part of the incident response capability: [Assignment: organization-defined types of dynamic reconfiguration].', 'kb-doc-14-nist-sp-800-53-p180-2', 0, 26, '14-nist-sp-800-53', 'retrieved', '0B362B5BCE0142BC3559CADA7D8913A48716C6D73E74184ABDB394C233D54B8A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
