INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p180-16', 'doc-14-nist-sp-800-53', '', 180, 'Discussion: Explicit focus on handling incidents involving insider threats provides additional emphasis on this type of threat and the need for specific incident handling capabilities to provide appropriate and timely responses.', 'kb-doc-14-nist-sp-800-53-p180-16', 0, 31, '14-nist-sp-800-53', 'retrieved', '13D1852B9A56EF16A045C1954C94E01B8785A135040D31ABC0C878561230AE04', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
