INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p181-3', 'doc-14-nist-sp-800-53', '', 181, '(7) INCIDENT HANDLING | INSIDER THREATS — INTRA-ORGANIZATION COORDINATION Coordinate an incident handling capability for insider threats that includes the following organizational entities [Assignment: organization-defined entities].', 'kb-doc-14-nist-sp-800-53-p181-3', 0, 26, '14-nist-sp-800-53', 'retrieved', 'AD31E135BB4F1982B1E67994F2D1A5E1766E3F14D97E8D23E54A5279A2459434', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
