INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p181-4', 'doc-14-nist-sp-800-53', '', 181, 'Discussion: Incident handling for insider threat incidents (e.g., preparation, detection and analysis, containment, eradication, and recovery) requires coordination among many organizational entities, including mission or business owners, system owners, human resources offices, procurement offices, personnel offices, physical security offices, senior agency information security officer, operations personnel, risk executive (function), senior agency official for privacy, and legal counsel. In addition, organizations may require external support from federal, state, and local law enforcement agencies.', 'kb-doc-14-nist-sp-800-53-p181-4', 0, 72, '14-nist-sp-800-53', 'retrieved', '78E4B1C7DF5BBC5C913564A2FA278BEE7BC406AA5F5AF2B48B8C7ACDFF43FD64', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p181-6', 'doc-14-nist-sp-800-53', '', 181, '(8) INCIDENT HANDLING | CORRELATION WITH EXTERNAL ORGANIZATIONS Coordinate with [Assignment: organization-defined external organizations] to correlate and share [Assignment: organization-defined incident information] to achieve a cross- organization perspective on incident awareness and more effective incident responses.', 'kb-doc-14-nist-sp-800-53-p181-6', 0, 36, '14-nist-sp-800-53', 'retrieved', 'F02469FB1B75D3239E2DBA4FC140D62D294773EAB406C985262F165FA4E930D1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p181-7', 'doc-14-nist-sp-800-53', '', 181, 'Discussion: The coordination of incident information with external organizations— including mission or business partners, military or coalition partners, customers, and developers— can provide significant benefits. Cross-organizational coordination can serve as an important risk management capability. This capability allows organizations to leverage information from a variety of sources to effectively respond to incidents and breaches that could potentially affect the organization’s operations, assets, and individuals.', 'kb-doc-14-nist-sp-800-53-p181-7', 0, 64, '14-nist-sp-800-53', 'retrieved', '449FBFE862DB2CA636D23D5BCB2507E71EE891EE941671A035549501A3062B04', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p181-9', 'doc-14-nist-sp-800-53', '', 181, '(9) INCIDENT HANDLING | DYNAMIC RESPONSE CAPABILITY Employ [Assignment: organization-defined dynamic response capabilities] to respond to incidents.', 'kb-doc-14-nist-sp-800-53-p181-9', 0, 17, '14-nist-sp-800-53', 'retrieved', 'C04153EF0978373EC5ED8735D680AC4B16D67804E3347C0C8D41DBE7D75F7076', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p181-10', 'doc-14-nist-sp-800-53', '', 181, 'Discussion: The dynamic response capability addresses the timely deployment of new or replacement organizational capabilities in response to incidents. This includes capabilities implemented at the mission and business process level and at the system level.', 'kb-doc-14-nist-sp-800-53-p181-10', 0, 35, '14-nist-sp-800-53', 'retrieved', 'C9E64DD8FE5EAD3D06C1D12ED571C4DEB33E02CF65370973E0EBDE01E5FD7249', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
