INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p181-12', 'doc-14-nist-sp-800-53', '', 181, '(10) INCIDENT HANDLING | SUPPLY CHAIN COORDINATION Coordinate incident handling activities involving supply chain events with other organizations involved in the supply chain.', 'kb-doc-14-nist-sp-800-53-p181-12', 0, 23, '14-nist-sp-800-53', 'retrieved', '515F0724401D514CFD02F9774212C9935F8C6DAC9BAB6F685D231862118C201A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p181-13', 'doc-14-nist-sp-800-53', '', 181, 'Discussion: Organizations involved in supply chain activities include product developers, system integrators, manufacturers, packagers, assemblers, distributors, vendors, and resellers. Supply chain incidents can occur anywhere through or to the supply chain and include compromises or breaches that involve primary or sub-tier providers, information technology products, system components, development processes or personnel, and distribution processes or warehousing facilities. Organizations consider including processes for protecting and sharing incident information in information exchange agreements and their obligations for reporting incidents to government oversight bodies (e.g., Federal Acquisition Security Council).', 'kb-doc-14-nist-sp-800-53-p181-13', 0, 86, '14-nist-sp-800-53', 'retrieved', '4D380E85DCE06D2A18E42DAA7741DE5466CF78B103647217342B6A33D88BFB61', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p181-15', 'doc-14-nist-sp-800-53', '', 181, '(11) INCIDENT HANDLING | INTEGRATED INCIDENT RESPONSE TEAM Establish and maintain an integrated incident response team that can be deployed to any location identified by the organization in [Assignment: organization-defined time period].', 'kb-doc-14-nist-sp-800-53-p181-15', 0, 32, '14-nist-sp-800-53', 'retrieved', 'F5FB2E14A59115D4110C5ED46D184F76E479AC02371DD798314767A3B126FF01', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
