INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p183-3', 'doc-14-nist-sp-800-53', '', 183, 'These sources include perimeter defenses, network devices (e.g., routers, switches), and endpoint agent data feeds. The SOC provides a holistic situational awareness capability to help organizations determine the security posture of the system and organization. A SOC capability can be obtained in a variety of ways. Larger organizations may implement a dedicated SOC while smaller organizations may employ third-party organizations to provide such a capability.', 'kb-doc-14-nist-sp-800-53-p183-3', 0, 65, '14-nist-sp-800-53', 'retrieved', '21A5B6D57CE482B31F84D6F0EB86686A7FC5DAE8C19FA9B8A0F9F8AD4D1027BF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p183-5', 'doc-14-nist-sp-800-53', '', 183, '(15) INCIDENT HANDLING | PUBLIC RELATIONS AND REPUTATION REPAIR (a) Manage public relations associated with an incident; and (b) Employ measures to repair the reputation of the organization.', 'kb-doc-14-nist-sp-800-53-p183-5', 0, 28, '14-nist-sp-800-53', 'retrieved', 'AF52CC44F7A4D06A82B4FAF212D8BC7C06C47D32E9ED6D9EC3C146415D75E15B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p183-6', 'doc-14-nist-sp-800-53', '', 183, 'Discussion: It is important for an organization to have a strategy in place for addressing incidents that have been brought to the attention of the general public, have cast the organization in a negative light, or have affected the organization’s constituents (e.g., partners, customers). Such publicity can be extremely harmful to the organization and affect its ability to carry out its mission and business functions. Taking proactive steps to repair the organization’s reputation is an essential aspect of reestablishing the trust and confidence of its constituents.', 'kb-doc-14-nist-sp-800-53-p183-6', 0, 86, '14-nist-sp-800-53', 'retrieved', '9227144DAF202EAD4CE28600F94635642460BB196A52CFB74D57D753E0B7BC0C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p183-8', 'doc-14-nist-sp-800-53', '', 183, 'References: [FASC18], [41 CFR 201], [OMB M-17-12], [SP 800-61], [SP 800-86], [SP 800-101], [SP 800-150], [SP 800-160-2], [SP 800-184], [IR 7559].', 'kb-doc-14-nist-sp-800-53-p183-8', 0, 21, '14-nist-sp-800-53', 'retrieved', 'F28E6579DD2B9B22C484CDDBBE245397D8FDDBD6A65EE16D922DDE0BB22BCD2F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
