INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p183-12', 'doc-14-nist-sp-800-53', '', 183, 'Control Enhancements: (1) INCIDENT MONITORING | AUTOMATED TRACKING, DATA COLLECTION, AND ANALYSIS Track incidents and collect and analyze incident information using [Assignment: organization-defined automated mechanisms].', 'kb-doc-14-nist-sp-800-53-p183-12', 0, 25, '14-nist-sp-800-53', 'retrieved', '5E49F1320F248E9788F25389321921602FE86797D2D2D1064B6A401B3F02E19B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
