INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p183-13', 'doc-14-nist-sp-800-53', '', 183, 'Discussion: Automated mechanisms for tracking incidents and collecting and analyzing incident information include Computer Incident Response Centers or other electronic databases of incidents and network monitoring devices.', 'kb-doc-14-nist-sp-800-53-p183-13', 0, 27, '14-nist-sp-800-53', 'retrieved', 'DF71BA3D35215999C1B1B34F214E3A60F3D8BF55630B666A0F3C14FE23B5222A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
