INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p184-1', 'doc-14-nist-sp-800-53', '', 184, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 157 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p184-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '7173E8525368AE4423A0A3310AD3BDB18AC8C5FBDF70CEEDB485040AA74A2AE5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
