INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p184-2', 'doc-14-nist-sp-800-53', '', 184, 'IR-6 INCIDENT REPORTING Control: a. Require personnel to report suspected incidents to the organizational incident response capability within [Assignment: organization-defined time period]; and b. Report incident information to [Assignment: organization-defined authorities].', 'kb-doc-14-nist-sp-800-53-p184-2', 0, 31, '14-nist-sp-800-53', 'retrieved', '4C3D4379571244CA451521780FF5CC5FC1DE5B9CFAFCA3BD4A57550C7B39C3B1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p184-3', 'doc-14-nist-sp-800-53', '', 184, 'Discussion: The types of incidents reported, the content and timeliness of the reports, and the designated reporting authorities reflect applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Incident information can inform risk assessments, control effectiveness assessments, security requirements for acquisitions, and selection criteria for technology products.', 'kb-doc-14-nist-sp-800-53-p184-3', 0, 48, '14-nist-sp-800-53', 'retrieved', '6F60FC96C644BB8FA03A56736CFBCF80A62E3DCBE27270574AE4B0035FFC364E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
