INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p184-5', 'doc-14-nist-sp-800-53', '', 184, 'Control Enhancements: (1) INCIDENT REPORTING | AUTOMATED REPORTING Report incidents using [Assignment: organization-defined automated mechanisms].', 'kb-doc-14-nist-sp-800-53-p184-5', 0, 15, '14-nist-sp-800-53', 'retrieved', 'CD14DC684F23589453673E1DFF9A726E05A8A598CD75A582003AF39254D65820', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
