INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p184-6', 'doc-14-nist-sp-800-53', '', 184, 'Discussion: The recipients of incident reports are specified in IR-6b. Automated reporting mechanisms include email, posting on websites (with automatic updates), and automated incident response tools and programs.', 'kb-doc-14-nist-sp-800-53-p184-6', 0, 28, '14-nist-sp-800-53', 'retrieved', '33C918B075A4A79D10DA88812A1E2998F802A9D45DC102CB7CAFC0E2BB63EC43', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p184-8', 'doc-14-nist-sp-800-53', '', 184, '(2) INCIDENT REPORTING | VULNERABILITIES RELATED TO INCIDENTS Report system vulnerabilities associated with reported incidents to [Assignment: organization-defined personnel or roles].', 'kb-doc-14-nist-sp-800-53-p184-8', 0, 21, '14-nist-sp-800-53', 'retrieved', '05EABEA210EDB64CF924482A7B954854F2FC7C911345FCF0C6FD919C15E58B70', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p184-9', 'doc-14-nist-sp-800-53', '', 184, 'Discussion: Reported incidents that uncover system vulnerabilities are analyzed by organizational personnel including system owners, mission and business owners, senior agency information security officers, senior agency officials for privacy, authorizing officials, and the risk executive (function). The analysis can serve to prioritize and initiate mitigation actions to address the discovered system vulnerability.', 'kb-doc-14-nist-sp-800-53-p184-9', 0, 52, '14-nist-sp-800-53', 'retrieved', '2A60986EE4A4DB368246FDA711122DDBBF15ABA9AAF6329A7A41D7FDD9ECC34D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p184-11', 'doc-14-nist-sp-800-53', '', 184, '(3) INCIDENT REPORTING | SUPPLY CHAIN COORDINATION Provide incident information to the provider of the product or service and other organizations involved in the supply chain or supply chain governance for systems or system components related to the incident.', 'kb-doc-14-nist-sp-800-53-p184-11', 0, 39, '14-nist-sp-800-53', 'retrieved', '7E4F0460CAD7F44BC26A4518DCFB08323694C28046F29A49B8DA657A5C30444B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p184-12', 'doc-14-nist-sp-800-53', '', 184, 'Discussion: Organizations involved in supply chain activities include product developers, system integrators, manufacturers, packagers, assemblers, distributors, vendors, and resellers. Entities that provide supply chain governance include the Federal Acquisition Security Council (FASC). Supply chain incidents include compromises or breaches that involve information technology products, system components, development processes or personnel, distribution processes, or warehousing facilities. Organizations determine the appropriate information to share and consider the value gained from informing external organizations about supply chain incidents, including the ability to improve processes or to identify the root cause of an incident.', 'kb-doc-14-nist-sp-800-53-p184-12', 0, 90, '14-nist-sp-800-53', 'retrieved', '394A9B1F2892D0415E5C6375B7D14D87665FBDEC7FD843B4EADB27EFF37709EA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
