VALUES ('doc-14-nist-sp-800-53-p185-2', 'doc-14-nist-sp-800-53', '', 185, 'IR-7 INCIDENT RESPONSE ASSISTANCE Control: Provide an incident response support resource, integral to the organizational incident response capability, that offers advice and assistance to users of the system for the handling and reporting of incidents.', 'kb-doc-14-nist-sp-800-53-p185-2', 0, 35, '14-nist-sp-800-53', 'retrieved', '570879FA0F163C333187E85051989FBC770D63AC22A4DAAB9CBFE6DB04A00048', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p185-3', 'doc-14-nist-sp-800-53', '', 185, 'Discussion: Incident response support resources provided by organizations include help desks, assistance groups, automated ticketing systems to open and track incident response tickets, and access to forensics services or consumer redress services, when required.', 'kb-doc-14-nist-sp-800-53-p185-3', 0, 34, '14-nist-sp-800-53', 'retrieved', '4B28D0C488D269E4BCAC441482C094D78E8C028744CDAEF599C22A0BFD2A8723', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
