INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p185-5', 'doc-14-nist-sp-800-53', '', 185, 'Control Enhancements: (1) INCIDENT RESPONSE ASSISTANCE | AUTOMATION SUPPORT FOR AVAILABILITY OF INFORMATION AND SUPPORT Increase the availability of incident response information and support using [Assignment: organization-defined automated mechanisms].', 'kb-doc-14-nist-sp-800-53-p185-5', 0, 29, '14-nist-sp-800-53', 'retrieved', '84F9145571DCFC4546B15F54245A4A04976A802F14BD6A7385C1C39EAE3BB69A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
