INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p185-6', 'doc-14-nist-sp-800-53', '', 185, 'Discussion: Automated mechanisms can provide a push or pull capability for users to obtain incident response assistance. For example, individuals may have access to a website to query the assistance capability, or the assistance capability can proactively send incident response information to users (general distribution or targeted) as part of increasing understanding of current response capabilities and support.', 'kb-doc-14-nist-sp-800-53-p185-6', 0, 58, '14-nist-sp-800-53', 'retrieved', 'CC62D3459F15A05E9768B599BA178AE32C6D1C3BC2BABB7CCE90E2DFFBDCE80D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
