INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p186-5', 'doc-14-nist-sp-800-53', '', 186, 'Related Controls: AC-2, CP-2, CP-4, IR-4, IR-7, IR-9, PE-6, PL-2, SA-15, SI-12, SR-8.', 'kb-doc-14-nist-sp-800-53-p186-5', 0, 13, '14-nist-sp-800-53', 'retrieved', 'D83FEC6CB6A5B85643E34396232B30781DB6182CB622838FC3861A6E7DB817A3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
