INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p186-6', 'doc-14-nist-sp-800-53', '', 186, 'Control Enhancements: (1) INCIDENT RESPONSE PLAN | BREACHES Include the following in the Incident Response Plan for breaches involving personally identifiable information: (a) A process to determine if notice to individuals or other organizations, including oversight organizations, is needed; (b) An assessment process to determine the extent of the harm, embarrassment, inconvenience, or unfairness to affected individuals and any mechanisms to mitigate such harms; and (c) Identification of applicable privacy requirements.', 'kb-doc-14-nist-sp-800-53-p186-6', 0, 71, '14-nist-sp-800-53', 'retrieved', '6E95EBA3DA02C85A57C8F31111035A6CB735F594B69E8CFF0E0CDDB0EFE3F073', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p186-7', 'doc-14-nist-sp-800-53', '', 186, 'Discussion: Organizations may be required by law, regulation, or policy to follow specific procedures relating to breaches, including notice to individuals, affected organizations, and oversight bodies; standards of harm; and mitigation or other specific requirements.', 'kb-doc-14-nist-sp-800-53-p186-7', 0, 35, '14-nist-sp-800-53', 'retrieved', '5D68609364A38C497A85289C5569BB2A365BB9A2F5F33EAFC5A667F9705C8AA5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
