INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p186-10', 'doc-14-nist-sp-800-53', '', 186, 'IR-9 INFORMATION SPILLAGE RESPONSE Control: Respond to information spills by: a. Assigning [Assignment: organization-defined personnel or roles] with responsibility for responding to information spills;', 'kb-doc-14-nist-sp-800-53-p186-10', 0, 24, '14-nist-sp-800-53', 'retrieved', '2513A0E021904F22163E363F31269F767EE57346418D42011E6A9D12DB877125', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
