INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p187-1', 'doc-14-nist-sp-800-53', '', 187, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 160 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p187-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '0653D84924992433049AEAF8E643D662EDECC97397FAC4F676B93C9350C1D0C3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p187-2', 'doc-14-nist-sp-800-53', '', 187, 'b. Identifying the specific information involved in the system contamination; c. Alerting [Assignment: organization-defined personnel or roles] of the information spill using a method of communication not associated with the spill; d. Isolating the contaminated system or system component; e. Eradicating the information from the contaminated system or component; f. Identifying other systems or system components that may have been subsequently contaminated; and g. Performing the following additional actions: [Assignment: organization-defined actions].', 'kb-doc-14-nist-sp-800-53-p187-2', 0, 72, '14-nist-sp-800-53', 'retrieved', 'C671116D575176F0DB96658664C752FD3F0D8ABBB4A5E65F4A5609D0F47F1F68', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p187-3', 'doc-14-nist-sp-800-53', '', 187, 'Discussion: Information spillage refers to instances where information is placed on systems that are not authorized to process such information. Information spills occur when information that is thought to be a certain classification or impact level is transmitted to a system and subsequently is determined to be of a higher classification or impact level. At that point, corrective action is required. The nature of the response is based on the classification or impact level of the spilled information, the security capabilities of the system, the specific nature of the contaminated storage media, and the access authorizations of individuals with authorized access to the contaminated system. The methods used to communicate information about the spill after the fact do not involve methods directly associated with the actual spill to minimize the risk of further spreading the contamination before such contamination is isolated and eradicated.', 'kb-doc-14-nist-sp-800-53-p187-3', 0, 143, '14-nist-sp-800-53', 'retrieved', 'AB7B2581DF1FB8E389758F1B77429B40A2485E5437B8FD25A3A4A0FE74958C2C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p187-5', 'doc-14-nist-sp-800-53', '', 187, 'Control Enhancements: (1) INFORMATION SPILLAGE RESPONSE | RESPONSIBLE PERSONNEL [Withdrawn: Incorporated into IR-9.] (2) INFORMATION SPILLAGE RESPONSE | TRAINING Provide information spillage response training [Assignment: organization-defined frequency].', 'kb-doc-14-nist-sp-800-53-p187-5', 0, 27, '14-nist-sp-800-53', 'retrieved', '7BB065DB9E4D118327F09C00EE1993D647A1D1D165BA574A91A4A1D84FDB7103', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p187-6', 'doc-14-nist-sp-800-53', '', 187, 'Discussion: Organizations establish requirements for responding to information spillage incidents in incident response plans. Incident response training on a regular basis helps to ensure that organizational personnel understand their individual responsibilities and what specific actions to take when spillage incidents occur.', 'kb-doc-14-nist-sp-800-53-p187-6', 0, 41, '14-nist-sp-800-53', 'retrieved', 'E6E79D66B1086CBDB0E25E82469C5855D9CA03CC67A042D499381BDD22E84297', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p187-8', 'doc-14-nist-sp-800-53', '', 187, '(3) INFORMATION SPILLAGE RESPONSE | POST-SPILL OPERATIONS Implement the following procedures to ensure that organizational personnel impacted by information spills can continue to carry out assigned tasks while contaminated systems are undergoing corrective actions: [Assignment: organization-defined procedures].', 'kb-doc-14-nist-sp-800-53-p187-8', 0, 37, '14-nist-sp-800-53', 'retrieved', '7D63E2D3EA7BF6A377D17188860D77A8103CB97D12759E9477ECCE79FBCBB3EB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p187-9', 'doc-14-nist-sp-800-53', '', 187, 'Discussion: Corrective actions for systems contaminated due to information spillages may be time-consuming. Personnel may not have access to the contaminated systems while corrective actions are being taken, which may potentially affect their ability to conduct organizational business.', 'kb-doc-14-nist-sp-800-53-p187-9', 0, 38, '14-nist-sp-800-53', 'retrieved', 'ABFD7EDE038144697225934E46807A6AD1922502AEF8C7556262A305290AE20C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p187-11', 'doc-14-nist-sp-800-53', '', 187, '(4) INFORMATION SPILLAGE RESPONSE | EXPOSURE TO UNAUTHORIZED PERSONNEL Employ the following controls for personnel exposed to information not within assigned access authorizations: [Assignment: organization-defined controls].', 'kb-doc-14-nist-sp-800-53-p187-11', 0, 26, '14-nist-sp-800-53', 'retrieved', '33DA6D7026B4CE2EB8A1F890E8C8D916D2150E88DA8F92C097200991191245E2', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p187-12', 'doc-14-nist-sp-800-53', '', 187, 'Discussion: Controls include ensuring that personnel who are exposed to spilled information are made aware of the laws, executive orders, directives, regulations, policies, standards,', 'kb-doc-14-nist-sp-800-53-p187-12', 0, 24, '14-nist-sp-800-53', 'retrieved', 'E276594F1A89BF55AB15EEFEE17FCCF0BBD3994FA4652FA8D4434CCFF585AE21', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
