VALUES ('doc-14-nist-sp-800-53-p189-1', 'doc-14-nist-sp-800-53', '', 189, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 162 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p189-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '07F654D4BE59ACC058C09D9E637732F26C5DF594BA209C05D535495E4F3B1909', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
