VALUES ('doc-14-nist-sp-800-53-p190-4', 'doc-14-nist-sp-800-53', '', 190, 'Related Controls: CM-2, CM-3, CM-4, CM-5, CM-8, MA-4, MP-6, PE-16, SI-2, SR-3, SR-4, SR-11.', 'kb-doc-14-nist-sp-800-53-p190-4', 0, 14, '14-nist-sp-800-53', 'retrieved', '0646A7BD9F51F51C4A22DC6B735CF1164AFE8D07EBF99BF177EEB0B208B6FE8E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
