INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p190-5', 'doc-14-nist-sp-800-53', '', 190, 'Control Enhancements: (1) CONTROLLED MAINTENANCE | RECORD CONTENT [Withdrawn: Incorporated into MA-2.] (2) CONTROLLED MAINTENANCE | AUTOMATED MAINTENANCE ACTIVITIES (a) Schedule, conduct, and document maintenance, repair, and replacement actions for the system using [Assignment: organization-defined automated mechanisms]; and (b) Produce up-to date, accurate, and complete records of all maintenance, repair, and replacement actions requested, scheduled, in process, and completed.', 'kb-doc-14-nist-sp-800-53-p190-5', 0, 59, '14-nist-sp-800-53', 'retrieved', '9F4D10F83084C1B2C8D235DF6476CA03B3EE2A3113BBFCE103E79B6E36B05A08', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
