INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p190-6', 'doc-14-nist-sp-800-53', '', 190, 'Discussion: The use of automated mechanisms to manage and control system maintenance programs and activities helps to ensure the generation of timely, accurate, complete, and consistent maintenance records.', 'kb-doc-14-nist-sp-800-53-p190-6', 0, 28, '14-nist-sp-800-53', 'retrieved', 'C6A06E6896582C03DEC50890B007E40FBA630EF14AE5E08C81E8BB11ED3F6FC9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
