VALUES ('doc-14-nist-sp-800-53-p191-1', 'doc-14-nist-sp-800-53', '', 191, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 164 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p191-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'C18DE5CE3304A1BC9B9A808656072B18AB2DDDB4FB3B5B5C4345093AE2A60FAA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
