INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p192-6', 'doc-14-nist-sp-800-53', '', 192, 'Discussion: Maintenance tools that execute with increased system privilege can result in unauthorized access to organizational information and assets that would otherwise be inaccessible.', 'kb-doc-14-nist-sp-800-53-p192-6', 0, 24, '14-nist-sp-800-53', 'retrieved', '684FFF3944527C5F2AC3E738920BD0A38E1D500840BA4B07DA8CC9D56106BDD1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
