VALUES ('doc-14-nist-sp-800-53-p192-8', 'doc-14-nist-sp-800-53', '', 192, '(6) MAINTENANCE TOOLS | SOFTWARE UPDATES AND PATCHES Inspect maintenance tools to ensure the latest software updates and patches are installed.', 'kb-doc-14-nist-sp-800-53-p192-8', 0, 21, '14-nist-sp-800-53', 'retrieved', 'AC385CA43CDB469533F61672C5216A13F777A6E4BBEA8981EEFD87B5BA3AD322', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
