INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p192-9', 'doc-14-nist-sp-800-53', '', 192, 'Discussion: Maintenance tools using outdated and/or unpatched software can provide a threat vector for adversaries and result in a significant vulnerability for organizations.', 'kb-doc-14-nist-sp-800-53-p192-9', 0, 23, '14-nist-sp-800-53', 'retrieved', '2E3CA4F5C77C0315CA0F358D08E5C8B07386B8BC3C729991895AFC1B3D62B366', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
