VALUES ('doc-14-nist-sp-800-53-p192-15', 'doc-14-nist-sp-800-53', '', 192, 'Related Controls: AC-2, AC-3, AC-6, AC-17, AU-2, AU-3, IA-2, IA-4, IA-5, IA-8, MA-2, MA-5, PL-2, SC-7, SC-10.', 'kb-doc-14-nist-sp-800-53-p192-15', 0, 17, '14-nist-sp-800-53', 'retrieved', '3B6DFCA1670542328EAC0C6B9E8F43FB4AC55377D9798F34B154444FA4927FBD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
