VALUES ('doc-14-nist-sp-800-53-p193-1', 'doc-14-nist-sp-800-53', '', 193, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 166 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p193-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'EC706E02A73FD875A382D3036FD8F01E1614B6D30699CA66ECE56B78D2F09FA8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
