VALUES ('doc-14-nist-sp-800-53-p193-2', 'doc-14-nist-sp-800-53', '', 193, '(b) Review the audit records of the maintenance and diagnostic sessions to detect anomalous behavior.', 'kb-doc-14-nist-sp-800-53-p193-2', 0, 15, '14-nist-sp-800-53', 'retrieved', 'E939A55A2C3E7DB6FF99DF6B0C28FE6505E8064ACF4A3DFD2EAF18C192A71513', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
