INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p193-3', 'doc-14-nist-sp-800-53', '', 193, 'Discussion: Audit logging for nonlocal maintenance is enforced by AU-2. Audit events are defined in AU-2a.', 'kb-doc-14-nist-sp-800-53-p193-3', 0, 16, '14-nist-sp-800-53', 'retrieved', 'ED7673C00426FD36E51912B1441A0BF4F0F50C94F3FB294188543E4C9B909AEF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
