INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p193-5', 'doc-14-nist-sp-800-53', '', 193, '(2) NONLOCAL MAINTENANCE | DOCUMENT NONLOCAL MAINTENANCE [Withdrawn: Incorporated into MA-1 and MA-4.] (3) NONLOCAL MAINTENANCE | COMPARABLE SECURITY AND SANITIZATION (a) Require that nonlocal maintenance and diagnostic services be performed from a system that implements a security capability comparable to the capability implemented on the system being serviced; or (b) Remove the component to be serviced from the system prior to nonlocal maintenance or diagnostic services; sanitize the component (for organizational information); and after the service is performed, inspect and sanitize the component (for potentially malicious software) before reconnecting the component to the system.', 'kb-doc-14-nist-sp-800-53-p193-5', 0, 95, '14-nist-sp-800-53', 'retrieved', '0F7FD222345ADA45695F362C67E4F8ED2E851E05299E1000392D264B4F00F294', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p193-6', 'doc-14-nist-sp-800-53', '', 193, 'Discussion: Comparable security capability on systems, diagnostic tools, and equipment providing maintenance services implies that the implemented controls on those systems, tools, and equipment are at least as comprehensive as the controls on the system being serviced.', 'kb-doc-14-nist-sp-800-53-p193-6', 0, 37, '14-nist-sp-800-53', 'retrieved', '55255677ECE77988449543B1223100A4637F467A945CF772E0587327C9E6FFDB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p193-8', 'doc-14-nist-sp-800-53', '', 193, '(4) NONLOCAL MAINTENANCE | AUTHENTICATION AND SEPARATION OF MAINTENANCE SESSIONS Protect nonlocal maintenance sessions by: (a) Employing [Assignment: organization-defined authenticators that are replay resistant]; and (b) Separating the maintenance sessions from other network sessions with the system by either: (1) Physically separated communications paths; or (2) Logically separated communications paths.', 'kb-doc-14-nist-sp-800-53-p193-8', 0, 50, '14-nist-sp-800-53', 'retrieved', '3DF0646F345AAF97AFA08FC8D4CD07F893EA43E609C753B5344BF88F39141DF5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p193-11', 'doc-14-nist-sp-800-53', '', 193, '(5) NONLOCAL MAINTENANCE | APPROVALS AND NOTIFICATIONS (a) Require the approval of each nonlocal maintenance session by [Assignment: organization-defined personnel or roles]; and (b) Notify the following personnel or roles of the date and time of planned nonlocal maintenance: [Assignment: organization-defined personnel or roles].', 'kb-doc-14-nist-sp-800-53-p193-11', 0, 44, '14-nist-sp-800-53', 'retrieved', '4D5756B69D58C0C5C4975F068271FDBCC71DC1F7041BE23C5F7202F727BF159F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
