INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p193-12', 'doc-14-nist-sp-800-53', '', 193, 'Discussion: Notification may be performed by maintenance personnel. Approval of nonlocal maintenance is accomplished by personnel with sufficient information security and system knowledge to determine the appropriateness of the proposed maintenance.', 'kb-doc-14-nist-sp-800-53-p193-12', 0, 31, '14-nist-sp-800-53', 'retrieved', 'CB47A980D384AD49372322F4D3C962AC30F955AEBE08C33447C55C96785748BF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
