INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p194-5', 'doc-14-nist-sp-800-53', '', 194, 'Discussion: Verifying the termination of a connection once maintenance is completed ensures that connections established during nonlocal maintenance and diagnostic sessions have been terminated and are no longer available for use.', 'kb-doc-14-nist-sp-800-53-p194-5', 0, 31, '14-nist-sp-800-53', 'retrieved', '71FEF90DF4B3D0DF1EBCE152B3DD2D1008AB83DF4A082E5EE6966FE1A517B5F1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
