VALUES ('doc-14-nist-sp-800-53-p194-11', 'doc-14-nist-sp-800-53', '', 194, 'Related Controls: AC-2, AC-3, AC-5, AC-6, IA-2, IA-8, MA-4, MP-2, PE-2, PE-3, PS-7, RA-3.', 'kb-doc-14-nist-sp-800-53-p194-11', 0, 14, '14-nist-sp-800-53', 'retrieved', '4205332C63710EA6EC8260FF5D880B84E7F4D1B5633D12C7B7378727E186B5E6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
