VALUES ('doc-14-nist-sp-800-53-p195-1', 'doc-14-nist-sp-800-53', '', 195, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 168 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p195-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '27E131545716981D005149B26A5EB6CA1F30EA536B0A52A2458D3A97F88803B0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
