VALUES ('doc-14-nist-sp-800-53-p196-3', 'doc-14-nist-sp-800-53', '', 196, 'Discussion: Personnel who perform maintenance activities in other capacities not directly related to the system include physical plant personnel and custodial personnel.', 'kb-doc-14-nist-sp-800-53-p196-3', 0, 22, '14-nist-sp-800-53', 'retrieved', '19E3130574256F69E96FD9E0A03AFB40C231B07D3D4AB26C6A861CABD4613298', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
