INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p196-7', 'doc-14-nist-sp-800-53', '', 196, 'Discussion: Organizations specify the system components that result in increased risk to organizational operations and assets, individuals, other organizations, or the Nation when the functionality provided by those components is not operational. Organizational actions to obtain maintenance support include having appropriate contracts in place.', 'kb-doc-14-nist-sp-800-53-p196-7', 0, 44, '14-nist-sp-800-53', 'retrieved', '1AAF8E1FEC5D6E022E3230D734B0EFE9D4C21BD3A1822B4A13F5A32D21003076', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
