INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p196-9', 'doc-14-nist-sp-800-53', '', 196, 'Control Enhancements: (1) TIMELY MAINTENANCE | PREVENTIVE MAINTENANCE Perform preventive maintenance on [Assignment: organization-defined system components] at [Assignment: organization-defined time intervals].', 'kb-doc-14-nist-sp-800-53-p196-9', 0, 21, '14-nist-sp-800-53', 'retrieved', 'D5B7D3FDE0F8AAF7E75646ABE993A5FC36420AD8BE9C4A98EB813B2137C6E4EA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p196-10', 'doc-14-nist-sp-800-53', '', 196, 'Discussion: Preventive maintenance includes proactive care and the servicing of system components to maintain organizational equipment and facilities in satisfactory operating condition. Such maintenance provides for the systematic inspection, tests, measurements, adjustments, parts replacement, detection, and correction of incipient failures either before they occur or before they develop into major defects. The primary goal of preventive maintenance is to avoid or mitigate the consequences of equipment failures. Preventive maintenance is designed to preserve and restore equipment reliability by replacing worn components before they fail. Methods of determining what preventive (or other) failure management policies to apply include original equipment manufacturer recommendations; statistical failure records; expert opinion; maintenance that has already been conducted on similar equipment; requirements of codes, laws, or regulations within a jurisdiction; or measured values and performance indications.', 'kb-doc-14-nist-sp-800-53-p196-10', 0, 130, '14-nist-sp-800-53', 'retrieved', '42054452D16B3B326B85000378A65B09A4A22FF802211BA3DF6C7E4B05D18501', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
