VALUES ('doc-14-nist-sp-800-53-p197-2', 'doc-14-nist-sp-800-53', '', 197, '(3) TIMELY MAINTENANCE | AUTOMATED SUPPORT FOR PREDICTIVE MAINTENANCE Transfer predictive maintenance data to a maintenance management system using [Assignment: organization-defined automated mechanisms].', 'kb-doc-14-nist-sp-800-53-p197-2', 0, 23, '14-nist-sp-800-53', 'retrieved', '1639A2C3DFB93F2FCB5A0658176E49656004C1F7F37E54C2072C52F1C976D592', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
