INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p197-3', 'doc-14-nist-sp-800-53', '', 197, 'Discussion: A computerized maintenance management system maintains a database of information about the maintenance operations of organizations and automates the processing of equipment condition data to trigger maintenance planning, execution, and reporting.', 'kb-doc-14-nist-sp-800-53-p197-3', 0, 32, '14-nist-sp-800-53', 'retrieved', 'B051E9D318EF0DA290315E30D9E00A3F19CDA9534EE44C32F1CF055B056671EA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
