VALUES ('doc-14-nist-sp-800-53-p198-1', 'doc-14-nist-sp-800-53', '', 198, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 171 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p198-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '8B705ACCB1A5C31542E68B6D828E6C8C1B3BF9AC3698C471E1C479B2FA26C1A2', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
