VALUES ('doc-14-nist-sp-800-53-p199-1', 'doc-14-nist-sp-800-53', '', 199, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 172 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p199-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'C84A88E8C79D3E1418F282729C124646398C30C167FC297B414BA7A2DD3C3F55', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
