VALUES ('doc-14-nist-sp-800-53-p199-5', 'doc-14-nist-sp-800-53', '', 199, 'Control Enhancements: (1) MEDIA ACCESS | AUTOMATED RESTRICTED ACCESS [Withdrawn: Incorporated into MP-4(2).] (2) MEDIA ACCESS | CRYPTOGRAPHIC PROTECTION [Withdrawn: Incorporated into SC-28(1).] References: [OMB A-130], [FIPS 199], [SP 800-111].', 'kb-doc-14-nist-sp-800-53-p199-5', 0, 30, '14-nist-sp-800-53', 'retrieved', 'E94D7BA234707BE7D49993E7F3432CE3BD2900B8E8B4532E806E7D2FDCB78F03', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
