INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p199-6', 'doc-14-nist-sp-800-53', '', 199, 'MP-3 MEDIA MARKING Control: a. Mark system media indicating the distribution limitations, handling caveats, and applicable security markings (if any) of the information; and b. Exempt [Assignment: organization-defined types of system media] from marking if the media remain within [Assignment: organization-defined controlled areas].', 'kb-doc-14-nist-sp-800-53-p199-6', 0, 43, '14-nist-sp-800-53', 'retrieved', '79A3102DC0D59C5182599D7A43471D578CB6A41270D5A21AA81B0D5C52359BB6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p199-7', 'doc-14-nist-sp-800-53', '', 199, 'Discussion: Security marking refers to the application or use of human-readable security attributes. Digital media includes diskettes, magnetic tapes, external or removable hard disk drives (e.g., solid state, magnetic), flash drives, compact discs, and digital versatile discs. Non- digital media includes paper and microfilm. Controlled unclassified information is defined by the National Archives and Records Administration along with the appropriate safeguarding and dissemination requirements for such information and is codified in [32 CFR 2002]. Security markings are generally not required for media that contains information determined by organizations to be in the public domain or to be publicly releasable. Some organizations may require markings for public information indicating that the information is publicly releasable.', 'kb-doc-14-nist-sp-800-53-p199-7', 0, 114, '14-nist-sp-800-53', 'retrieved', '65C56B8909D26477568DCB6D6154EC3A88DEF16E1A0A966C5643D2E4B71555D2', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p199-8', 'doc-14-nist-sp-800-53', '', 199, 'System media marking reflects applicable laws, executive orders, directives, policies, regulations, standards, and guidelines.', 'kb-doc-14-nist-sp-800-53-p199-8', 0, 14, '14-nist-sp-800-53', 'retrieved', '14F55F27B30DEB8BD2BFA29FDAF1B6F6D84918454F181B048B386FCE0D8E4298', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
