VALUES ('doc-14-nist-sp-800-53-p200-1', 'doc-14-nist-sp-800-53', '', 200, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 173 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p200-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '78BCC30D5E809AF542BE8BAB801149E340F0DF63C47BBC726CE079A6AEA7ADF8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
