INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p200-2', 'doc-14-nist-sp-800-53', '', 200, 'a. Physically control and securely store [Assignment: organization-defined types of digital and/or non-digital media] within [Assignment: organization-defined controlled areas]; and b. Protect system media types defined in MP-4a until the media are destroyed or sanitized using approved equipment, techniques, and procedures.', 'kb-doc-14-nist-sp-800-53-p200-2', 0, 41, '14-nist-sp-800-53', 'retrieved', '3AE087293A49DC7E72CD61CA5DB29769D6151A6DB20BF626A717A7B03D405866', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
