VALUES ('doc-14-nist-sp-800-53-p200-6', 'doc-14-nist-sp-800-53', '', 200, 'Discussion: Automated mechanisms include keypads, biometric readers, or card readers on the external entries to media storage areas.', 'kb-doc-14-nist-sp-800-53-p200-6', 0, 18, '14-nist-sp-800-53', 'retrieved', 'BA33564AA32FC060B66DBC6DFFDBC27E2CC6249922A99126412BBE0061BBAA04', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
