INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p200-9', 'doc-14-nist-sp-800-53', '', 200, 'MP-5 MEDIA TRANSPORT Control: a. Protect and control [Assignment: organization-defined types of system media] during transport outside of controlled areas using [Assignment: organization-defined controls]; b. Maintain accountability for system media during transport outside of controlled areas; c. Document activities associated with the transport of system media; and d. Restrict the activities associated with the transport of system media to authorized personnel.', 'kb-doc-14-nist-sp-800-53-p200-9', 0, 61, '14-nist-sp-800-53', 'retrieved', 'D581AF04849907BE5CBB5125D6B6807E8ECE520C193B2565578EB9CF4E47F251', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
