VALUES ('doc-14-nist-sp-800-53-p201-1', 'doc-14-nist-sp-800-53', '', 201, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 174 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p201-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'C4E42D3A232D39D1CDA245C886B90207F850E31D0063B62654C5B1F2FB6F32B9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
