VALUES ('doc-14-nist-sp-800-53-p201-3', 'doc-14-nist-sp-800-53', '', 201, 'Authorized transport and courier personnel may include individuals external to the organization.', 'kb-doc-14-nist-sp-800-53-p201-3', 0, 12, '14-nist-sp-800-53', 'retrieved', 'E12995018309B5B2BAB3974A49B8CAA7C0D14274AC35F9926968908AD105BFFD', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
