INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p201-4', 'doc-14-nist-sp-800-53', '', 201, 'Maintaining accountability of media during transport includes restricting transport activities to authorized personnel and tracking and/or obtaining records of transport activities as the media moves through the transportation system to prevent and detect loss, destruction, or tampering.', 'kb-doc-14-nist-sp-800-53-p201-4', 0, 37, '14-nist-sp-800-53', 'retrieved', '0F15739356323F3A7AC752F3B0ABAF47F3AE9FB26D7707B7BFAFE05472EF99A6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
