INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p201-5', 'doc-14-nist-sp-800-53', '', 201, 'Organizations establish documentation requirements for activities associated with the transport of system media in accordance with organizational assessments of risk. Organizations maintain the flexibility to define record-keeping methods for the different types of media transport as part of a system of transport-related records.', 'kb-doc-14-nist-sp-800-53-p201-5', 0, 43, '14-nist-sp-800-53', 'retrieved', 'EAF1890139DC1061863EE90078DF4A7779970EFCFC7EC3B234CBF83E4B5DA826', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
