INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p201-7', 'doc-14-nist-sp-800-53', '', 201, 'Control Enhancements: (1) MEDIA TRANSPORT | PROTECTION OUTSIDE OF CONTROLLED AREAS [Withdrawn: Incorporated into MP-5.] (2) MEDIA TRANSPORT | DOCUMENTATION OF ACTIVITIES [Withdrawn: Incorporated into MP-5.] (3) MEDIA TRANSPORT | CUSTODIANS Employ an identified custodian during transport of system media outside of controlled areas.', 'kb-doc-14-nist-sp-800-53-p201-7', 0, 44, '14-nist-sp-800-53', 'retrieved', '6CDDB6668F5672638D4031100B90D760CBD91552123770554B2CC00DCBD9D1C4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
