INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p201-8', 'doc-14-nist-sp-800-53', '', 201, 'Discussion: Identified custodians provide organizations with specific points of contact during the media transport process and facilitate individual accountability. Custodial responsibilities can be transferred from one individual to another if an unambiguous custodian is identified.', 'kb-doc-14-nist-sp-800-53-p201-8', 0, 35, '14-nist-sp-800-53', 'retrieved', 'A2DAAEA2DEB2BF1255FC939C83B8930E296BB1FF3A72CF10619EE61AFA51DC62', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
