VALUES ('doc-14-nist-sp-800-53-p201-10', 'doc-14-nist-sp-800-53', '', 201, '(4) MEDIA TRANSPORT | CRYPTOGRAPHIC PROTECTION [Withdrawn: Incorporated into SC-28(1).] References: [FIPS 199], [SP 800-60-1], [SP 800-60-2].', 'kb-doc-14-nist-sp-800-53-p201-10', 0, 17, '14-nist-sp-800-53', 'retrieved', '8B0C7429ED010B1DE13C03972A4119FB62A8981A05861743643432C1F92B1B4E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
