VALUES ('doc-14-nist-sp-800-53-p202-4', 'doc-14-nist-sp-800-53', '', 202, 'Control Enhancements: (1) MEDIA SANITIZATION | REVIEW, APPROVE, TRACK, DOCUMENT, AND VERIFY Review, approve, track, document, and verify media sanitization and disposal actions.', 'kb-doc-14-nist-sp-800-53-p202-4', 0, 23, '14-nist-sp-800-53', 'retrieved', '9B86FAB61B0F2BFEF3756AEE0DC35B67004D69788E29772CF895BFDBEF451FD5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p202-5', 'doc-14-nist-sp-800-53', '', 202, 'Discussion: Organizations review and approve media to be sanitized to ensure compliance with records retention policies. Tracking and documenting actions include listing personnel who reviewed and approved sanitization and disposal actions, types of media sanitized, files stored on the media, sanitization methods used, date and time of the sanitization actions, personnel who performed the sanitization, verification actions taken and personnel who performed the verification, and the disposal actions taken. Organizations verify that the sanitization of the media was effective prior to disposal.', 'kb-doc-14-nist-sp-800-53-p202-5', 0, 82, '14-nist-sp-800-53', 'retrieved', 'F4CB8010503E62B1369DAA195BF39C0C706997590ED71F10E356565DBB942BCB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p202-7', 'doc-14-nist-sp-800-53', '', 202, '(2) MEDIA SANITIZATION | EQUIPMENT TESTING Test sanitization equipment and procedures [Assignment: organization-defined frequency] to ensure that the intended sanitization is being achieved.', 'kb-doc-14-nist-sp-800-53-p202-7', 0, 23, '14-nist-sp-800-53', 'retrieved', 'D09B737E0FEB932ED6C1D08B56F54911D8E14290BEA4B3A4B8CB8E71B0E070CB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
