INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p202-8', 'doc-14-nist-sp-800-53', '', 202, 'Discussion: Testing of sanitization equipment and procedures may be conducted by qualified and authorized external entities, including federal agencies or external service providers.', 'kb-doc-14-nist-sp-800-53-p202-8', 0, 23, '14-nist-sp-800-53', 'retrieved', '979A1B5FE5D54B923906D98354B7DF406233DC5883ECF3025CED06A803C96A72', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
