VALUES ('doc-14-nist-sp-800-53-p202-13', 'doc-14-nist-sp-800-53', '', 202, '(4) MEDIA SANITIZATION | CONTROLLED UNCLASSIFIED INFORMATION [Withdrawn: Incorporated into MP-6.] (5) MEDIA SANITIZATION | CLASSIFIED INFORMATION', 'kb-doc-14-nist-sp-800-53-p202-13', 0, 17, '14-nist-sp-800-53', 'retrieved', '96008B0D4AA2801E4F4317A90892F6ECB7457F2DA7566933EC4D2ABCE3E5DFBF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
