VALUES ('doc-14-nist-sp-800-53-p206-1', 'doc-14-nist-sp-800-53', '', 206, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 179 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p206-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'DF675A925EBFE24C15F8146EC1D9F15650898FA4D1DE153F7F1AD2865E5800AF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
