VALUES ('doc-14-nist-sp-800-53-p207-1', 'doc-14-nist-sp-800-53', '', 207, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 180 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p207-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '7B10D4839CD5D6847607F3D3B526A3DEC5590DBBBD68B069BE9BCDDDC13BB886', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
