VALUES ('doc-14-nist-sp-800-53-p207-4', 'doc-14-nist-sp-800-53', '', 207, 'Related Controls: AT-3, AU-9, IA-4, MA-5, MP-2, PE-3, PE-4, PE-5, PE-8, PM-12, PS-3, PS-4, PS-5, PS-6.', 'kb-doc-14-nist-sp-800-53-p207-4', 0, 16, '14-nist-sp-800-53', 'retrieved', '18CD18237A1DCB50F39479644945AB1933AC912902F66896B1BB5D052AD3E141', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
