VALUES ('doc-14-nist-sp-800-53-p207-6', 'doc-14-nist-sp-800-53', '', 207, 'Discussion: Role-based facility access includes access by authorized permanent and regular/routine maintenance personnel, duty officers, and emergency medical staff.', 'kb-doc-14-nist-sp-800-53-p207-6', 0, 19, '14-nist-sp-800-53', 'retrieved', '521D5BDCF542779E074B76DD3C7D2552243E1126E49072D102F6A0CD22C76D26', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
