INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p207-8', 'doc-14-nist-sp-800-53', '', 207, '(2) PHYSICAL ACCESS AUTHORIZATIONS | TWO FORMS OF IDENTIFICATION Require two forms of identification from the following forms of identification for visitor access to the facility where the system resides: [Assignment: organization-defined list of acceptable forms of identification].', 'kb-doc-14-nist-sp-800-53-p207-8', 0, 38, '14-nist-sp-800-53', 'retrieved', '68673209BC3DAB1B7ED86084830FAC9F2CB3DC133103332707CBBEA0CC6AD95E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
