INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p207-9', 'doc-14-nist-sp-800-53', '', 207, 'Discussion: Acceptable forms of identification include passports, REAL ID-compliant drivers’ licenses, and Personal Identity Verification (PIV) cards. For gaining access to facilities using automated mechanisms, organizations may use PIV cards, key cards, PINs, and biometrics.', 'kb-doc-14-nist-sp-800-53-p207-9', 0, 35, '14-nist-sp-800-53', 'retrieved', 'F1746E48F4B940AE5E11405070DEBA6C96C15D34AFADCA6D260274739F9515B1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
