INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p208-5', 'doc-14-nist-sp-800-53', '', 208, 'Related Controls: AT-3, AU-2, AU-6, AU-9, AU-13, CP-10, IA-3, IA-8, MA-5, MP-2, MP-4, PE-2, PE- 4, PE-5, PE-8, PS-2, PS-3, PS-6, PS-7, RA-3, SC-28, SI-4, SR-3.', 'kb-doc-14-nist-sp-800-53-p208-5', 0, 26, '14-nist-sp-800-53', 'retrieved', 'B99B85820B1A8EBA3D0CD299F3673AC7403466D019EDB27CA3C3A5DFC73D505E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
