INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p208-6', 'doc-14-nist-sp-800-53', '', 208, 'Control Enhancements: (1) PHYSICAL ACCESS CONTROL | SYSTEM ACCESS Enforce physical access authorizations to the system in addition to the physical access controls for the facility at [Assignment: organization-defined physical spaces containing one or more components of the system].', 'kb-doc-14-nist-sp-800-53-p208-6', 0, 39, '14-nist-sp-800-53', 'retrieved', '7E052A68F7F47628B9D419D0D705533424B44CAC34245693A58F8FCD12ABFD97', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
