INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p208-7', 'doc-14-nist-sp-800-53', '', 208, 'Discussion: Control of physical access to the system provides additional physical security for those areas within facilities where there is a concentration of system components.', 'kb-doc-14-nist-sp-800-53-p208-7', 0, 25, '14-nist-sp-800-53', 'retrieved', 'E56206B7F8D2AAEC3FE14D811C7E61F3C8D70FCB74BAE99B0EAB22C11ED683C6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
