INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p209-2', 'doc-14-nist-sp-800-53', '', 209, 'Perform security checks [Assignment: organization-defined frequency] at the physical perimeter of the facility or system for exfiltration of information or removal of system components.', 'kb-doc-14-nist-sp-800-53-p209-2', 0, 24, '14-nist-sp-800-53', 'retrieved', '9D6C4D59E0A1722834FE6D451C73EA48E036EE1E5C8D875AF5CADAC7BD994FAA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
