INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p209-3', 'doc-14-nist-sp-800-53', '', 209, 'Discussion: Organizations determine the extent, frequency, and/or randomness of security checks to adequately mitigate risk associated with exfiltration.', 'kb-doc-14-nist-sp-800-53-p209-3', 0, 18, '14-nist-sp-800-53', 'retrieved', '8853D8A15EF349BFDA1B48603705D14D11CB54235DD522AE650FB463F6B18DF6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
