INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p209-5', 'doc-14-nist-sp-800-53', '', 209, '(3) PHYSICAL ACCESS CONTROL | CONTINUOUS GUARDS Employ guards to control [Assignment: organization-defined physical access points] to the facility where the system resides 24 hours per day, 7 days per week.', 'kb-doc-14-nist-sp-800-53-p209-5', 0, 31, '14-nist-sp-800-53', 'retrieved', '6B5A14B928DCFBE1B76CE8AE297712CFA8E88734BA626261371325A1B7529A60', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
