INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p209-6', 'doc-14-nist-sp-800-53', '', 209, 'Discussion: Employing guards at selected physical access points to the facility provides a more rapid response capability for organizations. Guards also provide the opportunity for human surveillance in areas of the facility not covered by video surveillance.', 'kb-doc-14-nist-sp-800-53-p209-6', 0, 37, '14-nist-sp-800-53', 'retrieved', '43C861A8F450755EEB3CB4BAE1C0F4444E4B5017231F47CE37C712193682EC1A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p209-8', 'doc-14-nist-sp-800-53', '', 209, '(4) PHYSICAL ACCESS CONTROL | LOCKABLE CASINGS Use lockable physical casings to protect [Assignment: organization-defined system components] from unauthorized physical access.', 'kb-doc-14-nist-sp-800-53-p209-8', 0, 21, '14-nist-sp-800-53', 'retrieved', '57C11E0CB5C8DFEC55D5F49A374804C07E01D58B92619C85E8E717F651085776', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p209-9', 'doc-14-nist-sp-800-53', '', 209, 'Discussion: The greatest risk from the use of portable devices— such as smart phones, tablets, and notebook computers— is theft. Organizations can employ lockable, physical casings to reduce or eliminate the risk of equipment theft. Such casings come in a variety of sizes, from units that protect a single notebook computer to full cabinets that can protect multiple servers, computers, and peripherals. Lockable physical casings can be used in conjunction with cable locks or lockdown plates to prevent the theft of the locked casing containing the computer equipment.', 'kb-doc-14-nist-sp-800-53-p209-9', 0, 88, '14-nist-sp-800-53', 'retrieved', '29B2A7C4516646DD772AC91232E03E74940DB376E89A64EEA3C5EE2761D1FF8C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p209-11', 'doc-14-nist-sp-800-53', '', 209, '(5) PHYSICAL ACCESS CONTROL | TAMPER PROTECTION Employ [Assignment: organization-defined anti-tamper technologies] to [Selection (one or more): detect; prevent] physical tampering or alteration of [Assignment: organization- defined hardware components] within the system.', 'kb-doc-14-nist-sp-800-53-p209-11', 0, 32, '14-nist-sp-800-53', 'retrieved', 'B6BF7033989A383F15A3BE816115436CAE18A45487ACD7BA0DC7CDA16B5941E3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p209-12', 'doc-14-nist-sp-800-53', '', 209, 'Discussion: Organizations can implement tamper detection and prevention at selected hardware components or implement tamper detection at some components and tamper prevention at other components. Detection and prevention activities can employ many types of anti-tamper technologies, including tamper-detection seals and anti-tamper coatings. Anti-tamper programs help to detect hardware alterations through counterfeiting and other supply chain-related risks.', 'kb-doc-14-nist-sp-800-53-p209-12', 0, 56, '14-nist-sp-800-53', 'retrieved', 'FB662BD3305DA80C70B6BB77960D53BB7849BC60247066089AFB467AB7F60825', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
