VALUES ('doc-14-nist-sp-800-53-p209-14', 'doc-14-nist-sp-800-53', '', 209, '(6) PHYSICAL ACCESS CONTROL | FACILITY PENETRATION TESTING [Withdrawn: Incorporated into CA-8.] (7) PHYSICAL ACCESS CONTROL | PHYSICAL BARRIERS Limit access using physical barriers.', 'kb-doc-14-nist-sp-800-53-p209-14', 0, 24, '14-nist-sp-800-53', 'retrieved', 'ABF6BCE8DE91EB46929C371B355E05D60ADE0234BD9F87164D90FFB6F0899195', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
