INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p209-15', 'doc-14-nist-sp-800-53', '', 209, 'Discussion: Physical barriers include bollards, concrete slabs, jersey walls, and hydraulic active vehicle barriers.', 'kb-doc-14-nist-sp-800-53-p209-15', 0, 14, '14-nist-sp-800-53', 'retrieved', 'DEA8157579D654315D671BEBC6906A71ED5DB8DD6C3849ED46BA03FB1F6C4A68', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
