VALUES ('doc-14-nist-sp-800-53-p209-17', 'doc-14-nist-sp-800-53', '', 209, '(8) PHYSICAL ACCESS CONTROL | ACCESS CONTROL VESTIBULES Employ access control vestibules at [Assignment: organization-defined locations within the facility].', 'kb-doc-14-nist-sp-800-53-p209-17', 0, 19, '14-nist-sp-800-53', 'retrieved', '3327701AD85A9A9EBB743BABFECB4D5B357B50D2BE2FC56846A92220C73176AB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
