VALUES ('doc-14-nist-sp-800-53-p210-1', 'doc-14-nist-sp-800-53', '', 210, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 183 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p210-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'F6818EEAAA546C84149EC9FDD1E90CCB1EC68D85920E45AFF525B96C55C2E74C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
