INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p210-6', 'doc-14-nist-sp-800-53', '', 210, 'Discussion: Security controls applied to system distribution and transmission lines prevent accidental damage, disruption, and physical tampering. Such controls may also be necessary to prevent eavesdropping or modification of unencrypted transmissions. Security controls used to control physical access to system distribution and transmission lines include disconnected or locked spare jacks, locked wiring closets, protection of cabling by conduit or cable trays, and wiretapping sensors.', 'kb-doc-14-nist-sp-800-53-p210-6', 0, 64, '14-nist-sp-800-53', 'retrieved', 'A2A3666542E56E49FE410487C0248C7CE0BF994D098CEBB5E6126E4193EF796E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p210-10', 'doc-14-nist-sp-800-53', '', 210, 'PE-5 ACCESS CONTROL FOR OUTPUT DEVICES Control: Control physical access to output from [Assignment: organization-defined output devices] to prevent unauthorized individuals from obtaining the output.', 'kb-doc-14-nist-sp-800-53-p210-10', 0, 25, '14-nist-sp-800-53', 'retrieved', '6E9A5E001FE4CD8A513889D1F80699639D56135963FF12A0B9D76723C5AEDD97', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
