INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p210-11', 'doc-14-nist-sp-800-53', '', 210, 'Discussion: Controlling physical access to output devices includes placing output devices in locked rooms or other secured areas with keypad or card reader access controls and allowing access to authorized individuals only, placing output devices in locations that can be monitored by personnel, installing monitor or screen filters, and using headphones. Examples of output devices include monitors, printers, scanners, audio devices, facsimile machines, and copiers.', 'kb-doc-14-nist-sp-800-53-p210-11', 0, 65, '14-nist-sp-800-53', 'retrieved', 'B2845506F828B965CABADB533FDEB9EC52E690507D9083F25AF4D50B835A05F4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p210-13', 'doc-14-nist-sp-800-53', '', 210, 'Control Enhancements: (1) ACCESS CONTROL FOR OUTPUT DEVICES | ACCESS TO OUTPUT BY AUTHORIZED INDIVIDUALS [Withdrawn: Incorporated into PE-5.] (2) ACCESS CONTROL FOR OUTPUT DEVICES | LINK TO INDIVIDUAL IDENTITY Link individual identity to receipt of output from output devices.', 'kb-doc-14-nist-sp-800-53-p210-13', 0, 40, '14-nist-sp-800-53', 'retrieved', 'FC0F63E2F720D143DB100E9EF9B8FBA5E61E1AAD3CACC1975AFA44E16ED017FB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
