INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p210-14', 'doc-14-nist-sp-800-53', '', 210, 'Discussion: Methods for linking individual identity to the receipt of output from output devices include installing security functionality on facsimile machines, copiers, and printers.', 'kb-doc-14-nist-sp-800-53-p210-14', 0, 24, '14-nist-sp-800-53', 'retrieved', '91EFD6B1039F34C43C2828CC9F213E625BBE1F94F3FAD6B606218230D91EF0F1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p210-15', 'doc-14-nist-sp-800-53', '', 210, 'Such functionality allows organizations to implement authentication on output devices prior to the release of output to individuals.', 'kb-doc-14-nist-sp-800-53-p210-15', 0, 18, '14-nist-sp-800-53', 'retrieved', '54C5290B8FC0632600FCF7F8CD33562B4F4A3C601D063656C4D2E3F72848E4EC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
