VALUES ('doc-14-nist-sp-800-53-p211-1', 'doc-14-nist-sp-800-53', '', 211, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 184 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p211-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '81DD58E158094214B867356DC486F2FAEBDF0E5E0B02CC9839DCF63B2B19A4B0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
