VALUES ('doc-14-nist-sp-800-53-p211-3', 'doc-14-nist-sp-800-53', '', 211, '(3) ACCESS CONTROL FOR OUTPUT DEVICES | MARKING OUTPUT DEVICES [Withdrawn: Incorporated into PE-22.] References: [IR 8023].', 'kb-doc-14-nist-sp-800-53-p211-3', 0, 17, '14-nist-sp-800-53', 'retrieved', 'D7D4BEA6CBB666ECC0311866809250A807C6040D3F4B6D770245D1ABCF412B21', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
