VALUES ('doc-14-nist-sp-800-53-p212-1', 'doc-14-nist-sp-800-53', '', 212, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 185 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p212-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '2B18C533425F4363AAB37EDCA38AEAE7EC3ECABAC2CB51543320C534FB2D044C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
