VALUES ('doc-14-nist-sp-800-53-p212-2', 'doc-14-nist-sp-800-53', '', 212, 'systems and system monitoring capabilities to provide integrated threat coverage for the organization.', 'kb-doc-14-nist-sp-800-53-p212-2', 0, 13, '14-nist-sp-800-53', 'retrieved', '2B1038D64C688413443FEF5450880FBA499A0706339126B16CEB9D19C3C035FF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
