VALUES ('doc-14-nist-sp-800-53-p213-2', 'doc-14-nist-sp-800-53', '', 213, 'Maintain and review visitor access records using [Assignment: organization-defined automated mechanisms].', 'kb-doc-14-nist-sp-800-53-p213-2', 0, 11, '14-nist-sp-800-53', 'retrieved', '14B51927FB4A21B8C244F303D08AF8691C5DEF2F2D58C5ACE3BA5213DC6FD18C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
