INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p213-3', 'doc-14-nist-sp-800-53', '', 213, 'Discussion: Visitor access records may be stored and maintained in a database management system that is accessible by organizational personnel. Automated access to such records facilitates record reviews on a regular basis to determine if access authorizations are current and still required to support organizational mission and business functions.', 'kb-doc-14-nist-sp-800-53-p213-3', 0, 49, '14-nist-sp-800-53', 'retrieved', '217FA21E7752BB7A5FCD12B8D77CFFE1A041E497DBC578F32B8439F92A885A97', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
