INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p213-5', 'doc-14-nist-sp-800-53', '', 213, '(2) VISITOR ACCESS RECORDS | PHYSICAL ACCESS RECORDS [Withdrawn: Incorporated into PE-2.] (3) VISITOR ACCESS RECORDS | LIMIT PERSONALLY IDENTIFIABLE INFORMATION ELEMENTS Limit personally identifiable information contained in visitor access records to the following elements identified in the privacy risk assessment: [Assignment: organization- defined elements].', 'kb-doc-14-nist-sp-800-53-p213-5', 0, 45, '14-nist-sp-800-53', 'retrieved', 'B714F88E3C71ABBD1539BAF2A50C28D39D8714CABB101A9DDBFEAF1083591DB8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p213-6', 'doc-14-nist-sp-800-53', '', 213, 'Discussion: Organizations may have requirements that specify the contents of visitor access records. Limiting personally identifiable information in visitor access records when such information is not needed for operational purposes helps reduce the level of privacy risk created by a system.', 'kb-doc-14-nist-sp-800-53-p213-6', 0, 41, '14-nist-sp-800-53', 'retrieved', '953B78E375BBCC998AB0ADAAD1219EC3CBC9E805A15A04F275FF09CDEEC3F23F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
