INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p213-9', 'doc-14-nist-sp-800-53', '', 213, 'PE-9 POWER EQUIPMENT AND CABLING Control: Protect power equipment and power cabling for the system from damage and destruction.', 'kb-doc-14-nist-sp-800-53-p213-9', 0, 19, '14-nist-sp-800-53', 'retrieved', 'F4B155D3A2B68142EFC73E1B422257B34EF889CFEA7016987B7244B1A95A8930', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
