INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p213-10', 'doc-14-nist-sp-800-53', '', 213, 'Discussion: Organizations determine the types of protection necessary for the power equipment and cabling employed at different locations that are both internal and external to organizational facilities and environments of operation. Types of power equipment and cabling include internal cabling and uninterruptable power sources in offices or data centers, generators and power cabling outside of buildings, and power sources for self-contained components such as satellites, vehicles, and other deployable systems.', 'kb-doc-14-nist-sp-800-53-p213-10', 0, 70, '14-nist-sp-800-53', 'retrieved', 'B0767FE126CDFAACA42EAA35D9ADC45848F7EDFBA88E977DEED1CA6162A36343', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p213-12', 'doc-14-nist-sp-800-53', '', 213, 'Control Enhancements: (1) POWER EQUIPMENT AND CABLING | REDUNDANT CABLING Employ redundant power cabling paths that are physically separated by [Assignment: organization-defined distance].', 'kb-doc-14-nist-sp-800-53-p213-12', 0, 23, '14-nist-sp-800-53', 'retrieved', 'A56F1B028E58E2640223BE663B3785FC3803C7D3DAF3204C5FAB204C789E5D09', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
