INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p213-13', 'doc-14-nist-sp-800-53', '', 213, 'Discussion: Physically separate and redundant power cables ensure that power continues to flow in the event that one of the cables is cut or otherwise damaged.', 'kb-doc-14-nist-sp-800-53-p213-13', 0, 26, '14-nist-sp-800-53', 'retrieved', 'A513F75AF25839181630BE00F2E2A2D5AC3D9A3E5AB8AAF163108742139E1A4C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
