VALUES ('doc-14-nist-sp-800-53-p213-15', 'doc-14-nist-sp-800-53', '', 213, '(2) POWER EQUIPMENT AND CABLING | AUTOMATIC VOLTAGE CONTROLS Employ automatic voltage controls for [Assignment: organization-defined critical system components].', 'kb-doc-14-nist-sp-800-53-p213-15', 0, 19, '14-nist-sp-800-53', 'retrieved', '4AFD05C6B3798E64101B8A5FD833D5E72DD950B304E509D353CD9787EC5072C3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
