INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p213-16', 'doc-14-nist-sp-800-53', '', 213, 'Discussion: Automatic voltage controls can monitor and control voltage. Such controls include voltage regulators, voltage conditioners, and voltage stabilizers.', 'kb-doc-14-nist-sp-800-53-p213-16', 0, 19, '14-nist-sp-800-53', 'retrieved', '0339ACF4E35B9BFFAAFE7DBE08634420FE152744EB19711969CDABF8D84AA3DE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
