INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p214-2', 'doc-14-nist-sp-800-53', '', 214, 'PE-10 EMERGENCY SHUTOFF Control: a. Provide the capability of shutting off power to [Assignment: organization-defined system or individual system components] in emergency situations; b. Place emergency shutoff switches or devices in [Assignment: organization-defined location by system or system component] to facilitate access for authorized personnel; and c. Protect emergency power shutoff capability from unauthorized activation.', 'kb-doc-14-nist-sp-800-53-p214-2', 0, 55, '14-nist-sp-800-53', 'retrieved', 'AABE1EE36324463F86460FEC585912CFB37EA10309EAB6B2191836B850DC891B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
