INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p214-3', 'doc-14-nist-sp-800-53', '', 214, 'Discussion: Emergency power shutoff primarily applies to organizational facilities that contain concentrations of system resources, including data centers, mainframe computer rooms, server rooms, and areas with computer-controlled machinery.', 'kb-doc-14-nist-sp-800-53-p214-3', 0, 28, '14-nist-sp-800-53', 'retrieved', '63945160326411EC92187013D539BD7E92CE37532ACB99B31A2E3D48BFFB26E6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
