VALUES ('doc-14-nist-sp-800-53-p214-5', 'doc-14-nist-sp-800-53', '', 214, 'Control Enhancements: (1) EMERGENCY SHUTOFF | ACCIDENTAL AND UNAUTHORIZED ACTIVATION [Withdrawn: Incorporated into PE-10.] References: None.', 'kb-doc-14-nist-sp-800-53-p214-5', 0, 16, '14-nist-sp-800-53', 'retrieved', 'BA823012DBDD090F513E445B6214087BCA5B5CEC810F6CB9560444EDC5974E74', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
