INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p214-10', 'doc-14-nist-sp-800-53', '', 214, 'Discussion: Provision of an alternate power supply with minimal operating capability can be satisfied by accessing a secondary commercial power supply or other external power supply.', 'kb-doc-14-nist-sp-800-53-p214-10', 0, 26, '14-nist-sp-800-53', 'retrieved', '233E2DFA1E707E4D187B03E84058EDC01E25C9D077D210DA2C6075C39CCC3953', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
