INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p215-7', 'doc-14-nist-sp-800-53', '', 215, 'Discussion: The provision of emergency lighting applies primarily to organizational facilities that contain concentrations of system resources, including data centers, server rooms, and mainframe computer rooms. Emergency lighting provisions for the system are described in the contingency plan for the organization. If emergency lighting for the system fails or cannot be provided, organizations consider alternate processing sites for power-related contingencies.', 'kb-doc-14-nist-sp-800-53-p215-7', 0, 60, '14-nist-sp-800-53', 'retrieved', '8A2B0680D0C49460F8BE7F3EB92A107F0BA9DE8861E77A5C312A89DDDB320DEE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
