VALUES ('doc-14-nist-sp-800-53-p215-9', 'doc-14-nist-sp-800-53', '', 215, 'Control Enhancements: (1) EMERGENCY LIGHTING | ESSENTIAL MISSION AND BUSINESS FUNCTIONS Provide emergency lighting for all areas within the facility supporting essential mission and business functions.', 'kb-doc-14-nist-sp-800-53-p215-9', 0, 26, '14-nist-sp-800-53', 'retrieved', 'ACA8F86F7B103003808B02474BF156D42719FDF5E1896FB7FC51385C1C322A17', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
