VALUES ('doc-14-nist-sp-800-53-p215-13', 'doc-14-nist-sp-800-53', '', 215, 'PE-13 FIRE PROTECTION Control: Employ and maintain fire detection and suppression systems that are supported by an independent energy source.', 'kb-doc-14-nist-sp-800-53-p215-13', 0, 20, '14-nist-sp-800-53', 'retrieved', 'E81D5612D748BA14900253A003BCC01DE8ADA9743212F94651E0458EA1E39B38', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
