VALUES ('doc-14-nist-sp-800-53-p216-4', 'doc-14-nist-sp-800-53', '', 216, '(2) FIRE PROTECTION | SUPPRESSION SYSTEMS — AUTOMATIC ACTIVATION AND NOTIFICATION (a) Employ fire suppression systems that activate automatically and notify [Assignment: organization-defined personnel or roles] and [Assignment: organization-defined emergency responders]; and (b) Employ an automatic fire suppression capability when the facility is not staffed on a continuous basis.', 'kb-doc-14-nist-sp-800-53-p216-4', 0, 49, '14-nist-sp-800-53', 'retrieved', 'B74E5306A17BD6BD827C18C7355D15871012BECB059EBCB1CB6DC3571303C82B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
