INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p216-5', 'doc-14-nist-sp-800-53', '', 216, 'Discussion: Organizations can identify specific personnel, roles, and emergency responders if individuals on the notification list need to have appropriate access authorizations and/or clearances (e.g., to enter to facilities where access is restricted due to the impact level or classification of information within the facility). Notification mechanisms may require independent energy sources to ensure that the notification capability is not adversely affected by the fire.', 'kb-doc-14-nist-sp-800-53-p216-5', 0, 65, '14-nist-sp-800-53', 'retrieved', '990CFFF35AC45BFB54E6E9C2C2208437C5D46EE65083F1EB583F557EFFA94DAE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
