INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p216-7', 'doc-14-nist-sp-800-53', '', 216, '(3) FIRE PROTECTION | AUTOMATIC FIRE SUPPRESSION [Withdrawn: Incorporated into PE-13(2).] (4) FIRE PROTECTION | INSPECTIONS Ensure that the facility undergoes [Assignment: organization-defined frequency] fire protection inspections by authorized and qualified inspectors and identified deficiencies are resolved within [Assignment: organization-defined time period].', 'kb-doc-14-nist-sp-800-53-p216-7', 0, 42, '14-nist-sp-800-53', 'retrieved', 'A83C5415D3F2D58557E9BAB5946C4F37EEBEBA8EFA854491159AF24016891425', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
