INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p216-8', 'doc-14-nist-sp-800-53', '', 216, 'Discussion: Authorized and qualified personnel within the jurisdiction of the organization include state, county, and city fire inspectors and fire marshals. Organizations provide escorts during inspections in situations where the systems that reside within the facilities contain sensitive information.', 'kb-doc-14-nist-sp-800-53-p216-8', 0, 39, '14-nist-sp-800-53', 'retrieved', '29E0FB11C7C93DF9AA91EB294FE8C5599048341608BFED10AA3CAF04C5C596C7', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
