INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p216-11', 'doc-14-nist-sp-800-53', '', 216, 'PE-14 ENVIRONMENTAL CONTROLS Control: a. Maintain [Selection (one or more): temperature; humidity; pressure; radiation; [Assignment: organization-defined environmental control]] levels within the facility where the system resides at [Assignment: organization-defined acceptable levels]; and b. Monitor environmental control levels [Assignment: organization-defined frequency].', 'kb-doc-14-nist-sp-800-53-p216-11', 0, 40, '14-nist-sp-800-53', 'retrieved', '0CCF38E1489EBE91508589F43CE74BEDF02AACC749538F8328190AF5029D44FB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
