INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p216-12', 'doc-14-nist-sp-800-53', '', 216, 'Discussion: The provision of environmental controls applies primarily to organizational facilities that contain concentrations of system resources (e.g., data centers, mainframe computer rooms, and server rooms). Insufficient environmental controls, especially in very harsh environments, can have a significant adverse impact on the availability of systems and system components that are needed to support organizational mission and business functions.', 'kb-doc-14-nist-sp-800-53-p216-12', 0, 58, '14-nist-sp-800-53', 'retrieved', 'CA21518265B840FDA1AB7C4B43CF16F3B10AD5E3E4D6484005726B92F0052F19', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
