INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p217-3', 'doc-14-nist-sp-800-53', '', 217, 'Discussion: The implementation of automatic environmental controls provides an immediate response to environmental conditions that can damage, degrade, or destroy organizational systems or systems components.', 'kb-doc-14-nist-sp-800-53-p217-3', 0, 25, '14-nist-sp-800-53', 'retrieved', '92B59C51BA97399F353746381B244288E927DE5F447AF6067A28F8897BB52112', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
