INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p217-5', 'doc-14-nist-sp-800-53', '', 217, '(2) ENVIRONMENTAL CONTROLS | MONITORING WITH ALARMS AND NOTIFICATIONS Employ environmental control monitoring that provides an alarm or notification of changes potentially harmful to personnel or equipment to [Assignment: organization- defined personnel or roles].', 'kb-doc-14-nist-sp-800-53-p217-5', 0, 34, '14-nist-sp-800-53', 'retrieved', '954E0CC800B347BF259A81AFE43BECC701AD7AD5A31771F4297EC1239A5C13EF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
