INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p217-6', 'doc-14-nist-sp-800-53', '', 217, 'Discussion: The alarm or notification may be an audible alarm or a visual message in real time to personnel or roles defined by the organization. Such alarms and notifications can help minimize harm to individuals and damage to organizational assets by facilitating a timely incident response.', 'kb-doc-14-nist-sp-800-53-p217-6', 0, 46, '14-nist-sp-800-53', 'retrieved', '18CBC8756FE183403A2A739FEDFF9F1E13B7BBA1269AF7A9CBFC2BE1713C5661', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
