INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p217-9', 'doc-14-nist-sp-800-53', '', 217, 'PE-15 WATER DAMAGE PROTECTION Control: Protect the system from damage resulting from water leakage by providing master shutoff or isolation valves that are accessible, working properly, and known to key personnel.', 'kb-doc-14-nist-sp-800-53-p217-9', 0, 31, '14-nist-sp-800-53', 'retrieved', '21A1F9C75AFE366763D23BE80C3ABCFA2C6BACE4FF5BD5D0D7984DADCA0D922D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
