INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p217-10', 'doc-14-nist-sp-800-53', '', 217, 'Discussion: The provision of water damage protection primarily applies to organizational facilities that contain concentrations of system resources, including data centers, server rooms, and mainframe computer rooms. Isolation valves can be employed in addition to or in lieu of master shutoff valves to shut off water supplies in specific areas of concern without affecting entire organizations.', 'kb-doc-14-nist-sp-800-53-p217-10', 0, 56, '14-nist-sp-800-53', 'retrieved', '81C01607AD792FE7802C0DC3D17A6AF0A7E155327592BE07208B17FFED4D47BB', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
