VALUES ('doc-14-nist-sp-800-53-p218-1', 'doc-14-nist-sp-800-53', '', 218, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 191 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p218-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '286CF0DA7D77A1E0D734B6CFEFB0810C47BF4543E660F67BDF9DFCB4161D3538', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
