VALUES ('doc-14-nist-sp-800-53-p218-13', 'doc-14-nist-sp-800-53', '', 218, 'PE-19 INFORMATION LEAKAGE Control: Protect the system from information leakage due to electromagnetic signals emanations.', 'kb-doc-14-nist-sp-800-53-p218-13', 0, 15, '14-nist-sp-800-53', 'retrieved', '0D1F792E2BAEA005D087B9B5D3129708FC4A870C5B5B03DE2BEA85B9ABF827DE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
