VALUES ('doc-14-nist-sp-800-53-p219-4', 'doc-14-nist-sp-800-53', '', 219, 'Control Enhancements: (1) INFORMATION LEAKAGE | NATIONAL EMISSIONS POLICIES AND PROCEDURES Protect system components, associated data communications, and networks in accordance with national Emissions Security policies and procedures based on the security category or classification of the information.', 'kb-doc-14-nist-sp-800-53-p219-4', 0, 38, '14-nist-sp-800-53', 'retrieved', '0B48414DE1440DDD6DCA91234E715EA05E7713AC707BF84095D28ED6ADE67AA2', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
