VALUES ('doc-14-nist-sp-800-53-p219-5', 'doc-14-nist-sp-800-53', '', 219, 'Discussion: Emissions Security (EMSEC) policies include the former TEMPEST policies.', 'kb-doc-14-nist-sp-800-53-p219-5', 0, 10, '14-nist-sp-800-53', 'retrieved', 'BA4C3DE8B5F54449897A2E45F06324229E33ACA7AEDC8F8231E8BDFEC88D4D15', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
