VALUES ('doc-14-nist-sp-800-53-p219-8', 'doc-14-nist-sp-800-53', '', 219, 'PE-20 ASSET MONITORING AND TRACKING Control: Employ [Assignment: organization-defined asset location technologies] to track and monitor the location and movement of [Assignment: organization-defined assets] within [Assignment: organization-defined controlled areas].', 'kb-doc-14-nist-sp-800-53-p219-8', 0, 29, '14-nist-sp-800-53', 'retrieved', '9D2EAB6783AB6C1C2EF4E2E5956A803FF76A9C585DE9B0D7E18CDEE02379E9EA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
