INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p219-9', 'doc-14-nist-sp-800-53', '', 219, 'Discussion: Asset location technologies can help ensure that critical assets— including vehicles, equipment, and system components— remain in authorized locations. Organizations consult with the Office of the General Counsel and senior agency official for privacy regarding the deployment and use of asset location technologies to address potential privacy concerns.', 'kb-doc-14-nist-sp-800-53-p219-9', 0, 49, '14-nist-sp-800-53', 'retrieved', '6A8EB3CD7F3AB7FD9FDE7120FC58AEA9ECC7FAAB26CA979081328F4C0521F9CE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
