VALUES ('doc-14-nist-sp-800-53-p220-2', 'doc-14-nist-sp-800-53', '', 220, 'Discussion: Hardware components that may require marking include input and output devices.', 'kb-doc-14-nist-sp-800-53-p220-2', 0, 12, '14-nist-sp-800-53', 'retrieved', 'EB204D66DEAEB962F3F190D8A219A35D1EB608CCD95500C295A45A4C65061712', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
