INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p220-3', 'doc-14-nist-sp-800-53', '', 220, 'Input devices include desktop and notebook computers, keyboards, tablets, and smart phones.', 'kb-doc-14-nist-sp-800-53-p220-3', 0, 12, '14-nist-sp-800-53', 'retrieved', 'A0433991E569147E0BE1F49FEC96F43F53E11C0541DABE4C8C76CA96729C5562', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p220-4', 'doc-14-nist-sp-800-53', '', 220, 'Output devices include printers, monitors/video displays, facsimile machines, scanners, copiers, and audio devices. Permissions controlling output to the output devices are addressed in AC-3 or AC-4. Components are marked to indicate the impact level or classification level of the system to which the devices are connected, or the impact level or classification level of the information permitted to be output. Security marking refers to the use of human-readable security attributes.', 'kb-doc-14-nist-sp-800-53-p220-4', 0, 70, '14-nist-sp-800-53', 'retrieved', '3855571577D5A589BEA4D253907CFB7ACDED7D54E8CC2DFF069E31A602B1D2B1', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p220-5', 'doc-14-nist-sp-800-53', '', 220, 'Security labeling refers to the use of security attributes for internal system data structures.', 'kb-doc-14-nist-sp-800-53-p220-5', 0, 14, '14-nist-sp-800-53', 'retrieved', '9B376B19B0F5C99D4256D6C449CE6E9E8302A044DE84ABF6B658E59DA269EEE3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p220-6', 'doc-14-nist-sp-800-53', '', 220, 'Security marking is generally not required for hardware components that process, store, or transmit information determined by organizations to be in the public domain or to be publicly releasable. However, organizations may require markings for hardware components that process, store, or transmit public information in order to indicate that such information is publicly releasable. Marking of system hardware components reflects applicable laws, executive orders, directives, policies, regulations, and standards.', 'kb-doc-14-nist-sp-800-53-p220-6', 0, 69, '14-nist-sp-800-53', 'retrieved', 'A13BEEBD83BFB34B0FB3CB6D0D88F7413A3DEC202136F14946F233C1629C7C6A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p220-10', 'doc-14-nist-sp-800-53', '', 220, 'PE-23 FACILITY LOCATION Control: a. Plan the location or site of the facility where the system resides considering physical and environmental hazards; and b. For existing facilities, consider the physical and environmental hazards in the organizational risk management strategy.', 'kb-doc-14-nist-sp-800-53-p220-10', 0, 39, '14-nist-sp-800-53', 'retrieved', '7986E53BC800924FF7B570F17231FD65F4F77A39A2ADEBE18651CBD531271A82', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p220-11', 'doc-14-nist-sp-800-53', '', 220, 'Discussion: Physical and environmental hazards include floods, fires, tornadoes, earthquakes, hurricanes, terrorism, vandalism, an electromagnetic pulse, electrical interference, and other forms of incoming electromagnetic radiation. The location of system components within the facility is addressed in PE-18.', 'kb-doc-14-nist-sp-800-53-p220-11', 0, 37, '14-nist-sp-800-53', 'retrieved', '5CA6836AE162EFFB47FC444906D001A59841474457E17DB44284307055D84E87', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
