VALUES ('doc-14-nist-sp-800-53-p222-1', 'doc-14-nist-sp-800-53', '', 222, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 195 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p222-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'E848F037FE20424AA330B62498C5F2FDF355B44111415F826F8FFDAAA5A82131', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
