INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p223-7', 'doc-14-nist-sp-800-53', '', 223, 'Control Enhancements: (1) SYSTEM SECURITY AND PRIVACY PLANS | CONCEPT OF OPERATIONS [Withdrawn: Incorporated into PL-7.] (2) SYSTEM SECURITY AND PRIVACY PLANS | FUNCTIONAL ARCHITECTURE [Withdrawn: Incorporated into PL-8.] (3) SYSTEM SECURITY AND PRIVACY PLANS | PLAN AND COORDINATE WITH OTHER ORGANIZATIONAL ENTITIES [Withdrawn: Incorporated into PL-2.] References: [OMB A-130], [SP 800-18], [SP 800-37], [SP 800-160-1], [SP 800-160-2].', 'kb-doc-14-nist-sp-800-53-p223-7', 0, 58, '14-nist-sp-800-53', 'retrieved', 'B897005FFDF78D095C6415FB71AD6DCB72116DC75155BC195823BBDE72CB9A8B', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
