VALUES ('doc-14-nist-sp-800-53-p224-1', 'doc-14-nist-sp-800-53', '', 224, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 197 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p224-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '6839B570FBFB0B1B984838BAE8A63ACACC3B2A9C7C80672A63C31B7CD9FB7400', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
