VALUES ('doc-14-nist-sp-800-53-p225-1', 'doc-14-nist-sp-800-53', '', 225, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 198 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p225-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '1C33706D49519894DC169302513758626DC5BC66132A38EDFABE409F81D1901C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
