VALUES ('doc-14-nist-sp-800-53-p226-1', 'doc-14-nist-sp-800-53', '', 226, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 199 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p226-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'B6B18031E2AC4516BF4221ABB3AA49E074990FAA2FC7BCCA552B1B1882D84003', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
