INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p226-2', 'doc-14-nist-sp-800-53', '', 226, 'also include other information, such as user roles and the access privileges assigned to each role; security and privacy requirements; types of information processed, stored, and transmitted by the system; supply chain risk management requirements; restoration priorities of information and system services; and other protection needs.', 'kb-doc-14-nist-sp-800-53-p226-2', 0, 46, '14-nist-sp-800-53', 'retrieved', '5994C04C7859CAAB43B770B2594D31D717DF6FA0A96F1AF69E6BD89A5FE89B74', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
