INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p227-4', 'doc-14-nist-sp-800-53', '', 227, '(2) SECURITY AND PRIVACY ARCHITECTURES | SUPPLIER DIVERSITY Require that [Assignment: organization-defined controls] allocated to [Assignment: organization-defined locations and architectural layers] are obtained from different suppliers.', 'kb-doc-14-nist-sp-800-53-p227-4', 0, 26, '14-nist-sp-800-53', 'retrieved', '26AE2A83209B3581908EA1F16170A404E096FFC738B062A55746D10A3BD020A8', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
