INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p227-5', 'doc-14-nist-sp-800-53', '', 227, 'Discussion: Information technology products have different strengths and weaknesses.', 'kb-doc-14-nist-sp-800-53-p227-5', 0, 9, '14-nist-sp-800-53', 'retrieved', '451D0D389478DF81499497B3D3CD7F39D5031B8860F62979BA2E84D82D117C72', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
