VALUES ('doc-14-nist-sp-800-53-p230-1', 'doc-14-nist-sp-800-53', '', 230, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 203 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p230-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '82BED6F3E74FF6BBF7A092FFDA71381BF280CA8F4779E8555593DE265801CA8C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
