VALUES ('doc-14-nist-sp-800-53-p231-1', 'doc-14-nist-sp-800-53', '', 231, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 204 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p231-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '708B40C421237124966E9BA00EE115B8F461055619A01CCEA77188C5855DB66A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
