VALUES ('doc-14-nist-sp-800-53-p233-1', 'doc-14-nist-sp-800-53', '', 233, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 206 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p233-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'C337469CDB1BE066B578A0B0DEAE3A7B75681423CB153B03F41E2B8CD96025DE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
