VALUES ('doc-14-nist-sp-800-53-p233-2', 'doc-14-nist-sp-800-53', '', 233, 'PM-5 SYSTEM INVENTORY Control: Develop and update [Assignment: organization-defined frequency] an inventory of organizational systems.', 'kb-doc-14-nist-sp-800-53-p233-2', 0, 15, '14-nist-sp-800-53', 'retrieved', '8E77D3242F028CC365131DBDCF4ECAF13208C848B7B6F0F42BB0C7E2B6F495E3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
