INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p233-9', 'doc-14-nist-sp-800-53', '', 233, 'PM-6 MEASURES OF PERFORMANCE Control: Develop, monitor, and report on the results of information security and privacy measures of performance.', 'kb-doc-14-nist-sp-800-53-p233-9', 0, 20, '14-nist-sp-800-53', 'retrieved', '15F03F23ECCAC62EBE6A2F688AC860DB74294EDA92CFF8271C682B2E58DFFCF3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
