VALUES ('doc-14-nist-sp-800-53-p234-1', 'doc-14-nist-sp-800-53', '', 234, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 207 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p234-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '637DE9CA696161A24D1137E3AD03B1E1C40A5C8941218240B10BC5F83F1AFDBF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
