INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p234-4', 'doc-14-nist-sp-800-53', '', 234, 'Control Enhancements: (1) ENTERPRISE ARCHITECTURE | OFFLOADING Offload [Assignment: organization-defined non-essential functions or services] to other systems, system components, or an external provider.', 'kb-doc-14-nist-sp-800-53-p234-4', 0, 23, '14-nist-sp-800-53', 'retrieved', '840BF849BE6E3B4616DB86BAB163D3E94586F6651C416A3D67DBC6D888E8D893', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p234-5', 'doc-14-nist-sp-800-53', '', 234, 'Discussion: Not every function or service that a system provides is essential to organizational mission or business functions. Printing or copying is an example of a non- essential but supporting service for an organization. Whenever feasible, such supportive but non-essential functions or services are not co-located with the functions or services that support essential mission or business functions. Maintaining such functions on the same system or system component increases the attack surface of the organization’s mission- essential functions or services. Moving supportive but non-essential functions to a non- critical system, system component, or external provider can also increase efficiency by putting those functions or services under the control of individuals or providers who are subject matter experts in the functions or services.', 'kb-doc-14-nist-sp-800-53-p234-5', 0, 122, '14-nist-sp-800-53', 'retrieved', '6C5625C5AEF84D5CDABD3626856C53685025E6C442C1B9913B37D8A1D1DF16A5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
