VALUES ('doc-14-nist-sp-800-53-p234-8', 'doc-14-nist-sp-800-53', '', 234, 'PM-8 CRITICAL INFRASTRUCTURE PLAN Control: Address information security and privacy issues in the development, documentation, and updating of a critical infrastructure and key resources protection plan.', 'kb-doc-14-nist-sp-800-53-p234-8', 0, 26, '14-nist-sp-800-53', 'retrieved', '0F8F95ABB101D8110CD2B8B00C2CC6DD2B6000B53145DDB07BBA3D83D8076247', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
