VALUES ('doc-14-nist-sp-800-53-p234-9', 'doc-14-nist-sp-800-53', '', 234, 'Discussion: Protection strategies are based on the prioritization of critical assets and resources.', 'kb-doc-14-nist-sp-800-53-p234-9', 0, 13, '14-nist-sp-800-53', 'retrieved', '90040517AC705937B4711A211367C67B3B19BD44DC3201D6AF1FBC2191018BBF', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
