INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p234-10', 'doc-14-nist-sp-800-53', '', 234, 'The requirement and guidance for defining critical infrastructure and key resources and for preparing an associated critical infrastructure protection plan are found in applicable laws, executive orders, directives, policies, regulations, standards, and guidelines.', 'kb-doc-14-nist-sp-800-53-p234-10', 0, 33, '14-nist-sp-800-53', 'retrieved', '47DB390069AC5A21C6636AAD9E21F0241AAD1B739A3580A09C0E737B4AC59320', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
