INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p234-14', 'doc-14-nist-sp-800-53', '', 234, 'PM-9 RISK MANAGEMENT STRATEGY Control: a. Develops a comprehensive strategy to manage: 1. Security risk to organizational operations and assets, individuals, other organizations, and the Nation associated with the operation and use of organizational systems; and 2. Privacy risk to individuals resulting from the authorized processing of personally identifiable information; b. Implement the risk management strategy consistently across the organization; and c. Review and update the risk management strategy [Assignment: organization-defined frequency] or as required, to address organizational changes.', 'kb-doc-14-nist-sp-800-53-p234-14', 0, 79, '14-nist-sp-800-53', 'retrieved', '6C1B6D8DF1B079C7DEE994FED0EFB0063187C8540155591CF75737D67E876268', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
