INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p235-6', 'doc-14-nist-sp-800-53', '', 235, 'PM-10 AUTHORIZATION PROCESS Control: a. Manage the security and privacy state of organizational systems and the environments in which those systems operate through authorization processes; b. Designate individuals to fulfill specific roles and responsibilities within the organizational risk management process; and c. Integrate the authorization processes into an organization-wide risk management program.', 'kb-doc-14-nist-sp-800-53-p235-6', 0, 52, '14-nist-sp-800-53', 'retrieved', '1A1DA3EFECCC1A9C3C1FC654C2F97E49B4FD19B4E67E4E624DA24AE35926F36F', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p235-7', 'doc-14-nist-sp-800-53', '', 235, 'Discussion: Authorization processes for organizational systems and environments of operation require the implementation of an organization-wide risk management process and associated security and privacy standards and guidelines. Specific roles for risk management processes include a risk executive (function) and designated authorizing officials for each organizational system and common control provider. The authorization processes for the organization are integrated with continuous monitoring processes to facilitate ongoing understanding and acceptance of security and privacy risks to organizational operations, organizational assets, individuals, other organizations, and the Nation.', 'kb-doc-14-nist-sp-800-53-p235-7', 0, 84, '14-nist-sp-800-53', 'retrieved', 'AF8ED30C19E4D7EA0EF5ACEA001B407A4DD26A9B2D570F1AF868CF1AA87CEB3A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p235-11', 'doc-14-nist-sp-800-53', '', 235, 'PM-11 MISSION AND BUSINESS PROCESS DEFINITION Control: a. Define organizational mission and business processes with consideration for information security and privacy and the resulting risk to organizational operations, organizational assets, individuals, other organizations, and the Nation; and b. Determine information protection and personally identifiable information processing needs arising from the defined mission and business processes; and', 'kb-doc-14-nist-sp-800-53-p235-11', 0, 56, '14-nist-sp-800-53', 'retrieved', '5B61997F4BAD0737A840BD8AA748982C14EF5B70A6A8DF60A7DDFA0CFF15919C', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
