INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p236-7', 'doc-14-nist-sp-800-53', '', 236, 'PM-12 INSIDER THREAT PROGRAM Control: Implement an insider threat program that includes a cross-discipline insider threat incident handling team.', 'kb-doc-14-nist-sp-800-53-p236-7', 0, 19, '14-nist-sp-800-53', 'retrieved', '3324F6F0E0C3C0DB2654894578ABA8E08B89F56DF1C810E276DA8062218A2418', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
