VALUES ('doc-14-nist-sp-800-53-p236-10', 'doc-14-nist-sp-800-53', '', 236, 'These precursors can guide organizational officials in more focused, targeted monitoring efforts.', 'kb-doc-14-nist-sp-800-53-p236-10', 0, 12, '14-nist-sp-800-53', 'retrieved', '5C32C0099D2ECA80991367498D69AF3547EF5F8834B3D399B56CF738459BC3CA', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
