VALUES ('doc-14-nist-sp-800-53-p237-3', 'doc-14-nist-sp-800-53', '', 237, 'Related Controls: AC-6, AT-2, AU-6, AU-7, AU-10, AU-12, AU-13, CA-7, IA-4, IR-4, MP-7, PE-2, PM- 16, PS-3, PS-4, PS-5, PS-7, PS-8, SC-7, SC-38, SI-4, PM-14.', 'kb-doc-14-nist-sp-800-53-p237-3', 0, 25, '14-nist-sp-800-53', 'retrieved', '5A093A145E8E3F7D80600A99DCAC2C463FCAA102C06C5C5C79D009A53BE719C0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
