INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p237-6', 'doc-14-nist-sp-800-53', '', 237, 'PM-13 SECURITY AND PRIVACY WORKFORCE Control: Establish a security and privacy workforce development and improvement program.', 'kb-doc-14-nist-sp-800-53-p237-6', 0, 16, '14-nist-sp-800-53', 'retrieved', 'D4EB4EC22DE0E7E51E7413F548269D53539FD23467803A19071AD76F0B746022', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
