VALUES ('doc-14-nist-sp-800-53-p238-9', 'doc-14-nist-sp-800-53', '', 238, 'PM-16 THREAT AWARENESS PROGRAM Control: Implement a threat awareness program that includes a cross-organization information- sharing capability for threat intelligence.', 'kb-doc-14-nist-sp-800-53-p238-9', 0, 20, '14-nist-sp-800-53', 'retrieved', '6ABA6CBF055E38BB9B03621D4241B6E3F3C3F0A67085692C1BF3B1F357008006', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
