INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p238-13', 'doc-14-nist-sp-800-53', '', 238, 'Discussion: To maximize the effectiveness of monitoring, it is important to know what threat observables and indicators the sensors need to be searching for. By using well-', 'kb-doc-14-nist-sp-800-53-p238-13', 0, 27, '14-nist-sp-800-53', 'retrieved', '3C995651A9D4DD71D2BD0CFD97EC38B458C4C558D111AA0B6980B63329496096', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
