VALUES ('doc-14-nist-sp-800-53-p239-2', 'doc-14-nist-sp-800-53', '', 239, 'established frameworks, services, and automated tools, organizations improve their ability to rapidly share and feed the relevant threat detection signatures into monitoring tools.', 'kb-doc-14-nist-sp-800-53-p239-2', 0, 23, '14-nist-sp-800-53', 'retrieved', '721740030FE67A9C5723D83BD9EC3FF7CDCF5F96576F8219A878D85C04FA5971', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
