INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p240-10', 'doc-14-nist-sp-800-53', '', 240, 'PM-19 PRIVACY PROGRAM LEADERSHIP ROLE Control: Appoint a senior agency official for privacy with the authority, mission, accountability, and resources to coordinate, develop, and implement, applicable privacy requirements and manage privacy risks through the organization-wide privacy program.', 'kb-doc-14-nist-sp-800-53-p240-10', 0, 37, '14-nist-sp-800-53', 'retrieved', '2A9D7FE186FBC737BCE89761A86F422A58DB44A4AA2E7B94548A0F928F54C80E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p240-11', 'doc-14-nist-sp-800-53', '', 240, 'Discussion: The privacy officer is an organizational official. For federal agencies— as defined by applicable laws, executive orders, directives, regulations, policies, standards, and guidelines— this official is designated as the senior agency official for privacy. Organizations may also refer to this official as the chief privacy officer. The senior agency official for privacy also has roles on the data management board (see PM-23) and the data integrity board (see PM-24).', 'kb-doc-14-nist-sp-800-53-p240-11', 0, 70, '14-nist-sp-800-53', 'retrieved', '3F70E4C24E96F9597FEDD1E0BF325FC42B94140C1D80E6225704029EEFE77BA5', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
ON CONFLICT(id) DO UPDATE SET text=excluded.text, embedding_id=excluded.embedding_id, source_id=excluded.source_id, content_hash=excluded.content_hash, processing_version='v1';
INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p240-15', 'doc-14-nist-sp-800-53', '', 240, 'PM-20 DISSEMINATION OF PRIVACY PROGRAM INFORMATION Control: Maintain a central resource webpage on the organization’s principal public website that serves as a central source of information about the organization’s privacy program and that: a. Ensures that the public has access to information about organizational privacy activities and can communicate with its senior agency official for privacy;', 'kb-doc-14-nist-sp-800-53-p240-15', 0, 56, '14-nist-sp-800-53', 'retrieved', '8BB252420CD0FD248645DE0A5C81BE47EF242A152F3518CB89FFE0BEB25F2235', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
