VALUES ('doc-14-nist-sp-800-53-p241-1', 'doc-14-nist-sp-800-53', '', 241, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 214 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p241-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'B7DE53ACA7C582C329489168B23EC27A7A21F6005AB91E0F911CBA56BE73862D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
