INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p241-2', 'doc-14-nist-sp-800-53', '', 241, 'b. Ensures that organizational privacy practices and reports are publicly available; and c. Employs publicly facing email addresses and/or phone lines to enable the public to provide feedback and/or direct questions to privacy offices regarding privacy practices.', 'kb-doc-14-nist-sp-800-53-p241-2', 0, 37, '14-nist-sp-800-53', 'retrieved', '57D2E77B9845907733AE2F529F908A04EC027CAB6C53CCF3346033B320FC37B4', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
