VALUES ('doc-14-nist-sp-800-53-p243-2', 'doc-14-nist-sp-800-53', '', 243, 'to record individual objections to the decisions, and a means of requesting reviews of the initial determinations.', 'kb-doc-14-nist-sp-800-53-p243-2', 0, 17, '14-nist-sp-800-53', 'retrieved', 'EF0A0E05AD47F5DA6A0CB3576724C7D0A38114FD9CBDC47E830ADDD4B1B0BE30', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
