VALUES ('doc-14-nist-sp-800-53-p244-1', 'doc-14-nist-sp-800-53', '', 244, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 217 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p244-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '2011096E2903F3A575CCEC8700B9CB04898B1082F97A09F7FB11580E5BA2A454', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
