VALUES ('doc-14-nist-sp-800-53-p246-2', 'doc-14-nist-sp-800-53', '', 246, 'owners or stewards, system owners, authorizing officials, senior agency information security officer, senior agency official for privacy, and senior accountable official for risk management.', 'kb-doc-14-nist-sp-800-53-p246-2', 0, 24, '14-nist-sp-800-53', 'retrieved', '6DFC01FBE921FF5C13262A5420151ABC7EE9DA320012BD30447C668D6FFEBF85', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
