INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p246-6', 'doc-14-nist-sp-800-53', '', 246, 'PM-29 RISK MANAGEMENT PROGRAM LEADERSHIP ROLES Control: a. Appoint a Senior Accountable Official for Risk Management to align organizational information security and privacy management processes with strategic, operational, and budgetary planning processes; and b. Establish a Risk Executive (function) to view and analyze risk from an organization-wide perspective and ensure management of risk is consistent across the organization.', 'kb-doc-14-nist-sp-800-53-p246-6', 0, 58, '14-nist-sp-800-53', 'retrieved', '6416ED5430C28942B3E2E9B169CE690215797D3E1D2CDB728FCEB58967A983E9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
