INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p246-7', 'doc-14-nist-sp-800-53', '', 246, 'Discussion: The senior accountable official for risk management leads the risk executive (function) in organization-wide risk management activities.', 'kb-doc-14-nist-sp-800-53-p246-7', 0, 18, '14-nist-sp-800-53', 'retrieved', 'A2AE42F63E06AB0F73F377716FD3A8A27F32C52CAB8E4F8137811A837939DAB0', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
