INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p247-2', 'doc-14-nist-sp-800-53', '', 247, '(1) SUPPLY CHAIN RISK MANAGEMENT STRATEGY | SUPPLIERS OF CRITICAL OR MISSION-ESSENTIAL ITEMS Identify, prioritize, and assess suppliers of critical or mission-essential technologies, products, and services.', 'kb-doc-14-nist-sp-800-53-p247-2', 0, 26, '14-nist-sp-800-53', 'retrieved', '0D3844CFAB7ECBC528CB9F1F26255CC5F2FC3D0197004FFEACFDF8AD74047EC3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
