INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p247-5', 'doc-14-nist-sp-800-53', '', 247, 'References: [PRIVACT], [FASC18], [EO 13873], [41 CFR 201], [OMB A-130], [OMB M-17-06] [CNSSD 505], [ISO 27036], [ISO 20243], [SP 800-161], [IR 8272].', 'kb-doc-14-nist-sp-800-53-p247-5', 0, 22, '14-nist-sp-800-53', 'retrieved', 'CE5B0FA9ED9BDF7329179FBE4F495870548D808FDFF7F401BB94B84559E1019D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
