VALUES ('doc-14-nist-sp-800-53-p250-1', 'doc-14-nist-sp-800-53', '', 250, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 223 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p250-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'D55B1D53893846BA4D0634102CFFA0F7FBAAF65DE373C5CC494AA291F07057B9', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
