VALUES ('doc-14-nist-sp-800-53-p251-1', 'doc-14-nist-sp-800-53', '', 251, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 224 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p251-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'CF34005D19D26F5EB22EC61143D52033A7B371FD80F44E3C4F767EA6E86A0994', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
