INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p251-2', 'doc-14-nist-sp-800-53', '', 251, 'information. Access authorizations are enforced by system access controls (see AC-3) and flow controls (see AC-4).', 'kb-doc-14-nist-sp-800-53-p251-2', 0, 16, '14-nist-sp-800-53', 'retrieved', '4865442DB1DCF82E7C1CCE9409F8FBC3F197B5C8951BAAC5014C81C0B4C1A995', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
