INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p251-4', 'doc-14-nist-sp-800-53', '', 251, '(2) PERSONNEL SCREENING | FORMAL INDOCTRINATION Verify that individuals accessing a system processing, storing, or transmitting types of classified information that require formal indoctrination, are formally indoctrinated for all the relevant types of information to which they have access on the system.', 'kb-doc-14-nist-sp-800-53-p251-4', 0, 42, '14-nist-sp-800-53', 'retrieved', 'FD9443D668F51887704CCC529CE24D841D393A3A5EB6260559A0DC66EACEC9D6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
