INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p251-5', 'doc-14-nist-sp-800-53', '', 251, 'Discussion: Types of classified information that require formal indoctrination include Special Access Program (SAP), Restricted Data (RD), and Sensitive Compartmented Information (SCI).', 'kb-doc-14-nist-sp-800-53-p251-5', 0, 22, '14-nist-sp-800-53', 'retrieved', '828B594A0984FF1BA931349D58E87C6507C00ACAA0A922D501D89087B5BAD0CC', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
