VALUES ('doc-14-nist-sp-800-53-p251-8', 'doc-14-nist-sp-800-53', '', 251, 'Discussion: Organizational information that requires special protection includes controlled unclassified information. Personnel security criteria include position sensitivity background screening requirements.', 'kb-doc-14-nist-sp-800-53-p251-8', 0, 20, '14-nist-sp-800-53', 'retrieved', '48A54D4F54EB4385D52C22CAD7EB88F1DF01CC8C5B12751258EE0E48BDFCC60A', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
