VALUES ('doc-14-nist-sp-800-53-p251-10', 'doc-14-nist-sp-800-53', '', 251, '(4) PERSONNEL SCREENING | CITIZENSHIP REQUIREMENTS Verify that individuals accessing a system processing, storing, or transmitting [Assignment: organization-defined information types] meet [Assignment: organization-defined citizenship requirements].', 'kb-doc-14-nist-sp-800-53-p251-10', 0, 25, '14-nist-sp-800-53', 'retrieved', '6920E427F7E2AE181136677D6FE447AC7311BA88628F897FA7F7C41EE55EEB66', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
