INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p252-2', 'doc-14-nist-sp-800-53', '', 252, 'in cases related to the unavailability of supervisors, illnesses, or job abandonment. Exit interviews are important for individuals with security clearances. The timely execution of termination actions is essential for individuals who have been terminated for cause. In certain situations, organizations consider disabling the system accounts of individuals who are being terminated prior to the individuals being notified.', 'kb-doc-14-nist-sp-800-53-p252-2', 0, 58, '14-nist-sp-800-53', 'retrieved', '5A94D9851A66B88E74A648A69F212C50CEEC96D8FCA2A9AC67C850D30B807188', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
