INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p252-4', 'doc-14-nist-sp-800-53', '', 252, 'Control Enhancements: (1) PERSONNEL TERMINATION | POST-EMPLOYMENT REQUIREMENTS (a) Notify terminated individuals of applicable, legally binding post-employment requirements for the protection of organizational information; and (b) Require terminated individuals to sign an acknowledgment of post-employment requirements as part of the organizational termination process.', 'kb-doc-14-nist-sp-800-53-p252-4', 0, 43, '14-nist-sp-800-53', 'retrieved', '2DBDB1BA5EED5D5B66F14EF2C03D901FC9EE68DB242A6B8C30D0D22A9B1B56EE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
