INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p252-5', 'doc-14-nist-sp-800-53', '', 252, 'Discussion: Organizations consult with the Office of the General Counsel regarding matters of post-employment requirements on terminated individuals.', 'kb-doc-14-nist-sp-800-53-p252-5', 0, 18, '14-nist-sp-800-53', 'retrieved', '20094AF5C6D1F2930BE6C21965B56873DF3A53EFCD2EDB1B5F0DAD6EC16DEFE3', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
