VALUES ('doc-14-nist-sp-800-53-p252-13', 'doc-14-nist-sp-800-53', '', 252, 'Actions that may be required for personnel transfers or reassignments to other positions within', 'kb-doc-14-nist-sp-800-53-p252-13', 0, 14, '14-nist-sp-800-53', 'retrieved', '452AD8CB23201D028918050A97F32E0EEE7BA9010E53AF4F054DDE8CAE1C2F2E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
