VALUES ('doc-14-nist-sp-800-53-p253-1', 'doc-14-nist-sp-800-53', '', 253, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 226 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p253-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'D36336639E4962492AE0FA6D5BDC270790A027EA7F710F30A5F75E82B4D28C34', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
