INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p253-6', 'doc-14-nist-sp-800-53', '', 253, 'PS-6 ACCESS AGREEMENTS Control: a. Develop and document access agreements for organizational systems; b. Review and update the access agreements [Assignment: organization-defined frequency]; and c. Verify that individuals requiring access to organizational information and systems: 1. Sign appropriate access agreements prior to being granted access; and 2. Re-sign access agreements to maintain access to organizational systems when access agreements have been updated or [Assignment: organization-defined frequency].', 'kb-doc-14-nist-sp-800-53-p253-6', 0, 66, '14-nist-sp-800-53', 'retrieved', 'B5B4BB2691B940C2DC03D155BFABA693E627C23932A3FAE832663E29C0F72CA6', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
