INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p253-7', 'doc-14-nist-sp-800-53', '', 253, 'Discussion: Access agreements include nondisclosure agreements, acceptable use agreements, rules of behavior, and conflict-of-interest agreements. Signed access agreements include an acknowledgement that individuals have read, understand, and agree to abide by the constraints associated with organizational systems to which access is authorized. Organizations can use electronic signatures to acknowledge access agreements unless specifically prohibited by organizational policy.', 'kb-doc-14-nist-sp-800-53-p253-7', 0, 57, '14-nist-sp-800-53', 'retrieved', '15BAAABEBB3C18A978A7EB471BEB7E1BD53FC73FDF3971D1BBD21A10C9F0EF1E', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
