INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p253-9', 'doc-14-nist-sp-800-53', '', 253, 'Control Enhancements: (1) ACCESS AGREEMENTS | INFORMATION REQUIRING SPECIAL PROTECTION [Withdrawn: Incorporated into PS-3.] (2) ACCESS AGREEMENTS | CLASSIFIED INFORMATION REQUIRING SPECIAL PROTECTION Verify that access to classified information requiring special protection is granted only to individuals who: (a) Have a valid access authorization that is demonstrated by assigned official government duties; (b) Satisfy associated personnel security criteria; and (c) Have read, understood, and signed a nondisclosure agreement.', 'kb-doc-14-nist-sp-800-53-p253-9', 0, 68, '14-nist-sp-800-53', 'retrieved', '0CA4ED495581BBBA9955E2349C906317DB5B9BE88CBD59E936D64A5638F8B189', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
