INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p253-10', 'doc-14-nist-sp-800-53', '', 253, 'Discussion: Classified information that requires special protection includes collateral information, Special Access Program (SAP) information, and Sensitive Compartmented Information (SCI). Personnel security criteria reflect applicable laws, executive orders, directives, regulations, policies, standards, and guidelines.', 'kb-doc-14-nist-sp-800-53-p253-10', 0, 34, '14-nist-sp-800-53', 'retrieved', '63B02864C587FDFBE00AACB25C8AC6F7566086925C5B7605C15C5796D3452FBE', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
