INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p254-11', 'doc-14-nist-sp-800-53', '', 254, 'PS-8 PERSONNEL SANCTIONS Control: a. Employ a formal sanctions process for individuals failing to comply with established information security and privacy policies and procedures; and b. Notify [Assignment: organization-defined personnel or roles] within [Assignment: organization-defined time period] when a formal employee sanctions process is initiated, identifying the individual sanctioned and the reason for the sanction.', 'kb-doc-14-nist-sp-800-53-p254-11', 0, 55, '14-nist-sp-800-53', 'retrieved', '6190D3FA9330AB69C755793E7A77F7957BA76426DF39923F349ED14458B8AE64', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
