VALUES ('doc-14-nist-sp-800-53-p255-5', 'doc-14-nist-sp-800-53', '', 255, 'PS-9 POSITION DESCRIPTIONS Control: Incorporate security and privacy roles and responsibilities into organizational position descriptions.', 'kb-doc-14-nist-sp-800-53-p255-5', 0, 15, '14-nist-sp-800-53', 'retrieved', '1D3FCB116ECDE7DBB1042F9DBA90177A2F381BDCD6C0BF2AD023A0A798E4483D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
