INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-14-nist-sp-800-53-p255-6', 'doc-14-nist-sp-800-53', '', 255, 'Discussion: Specification of security and privacy roles in individual organizational position descriptions facilitates clarity in understanding the security or privacy responsibilities associated with the roles and the role-based security and privacy training requirements for the roles.', 'kb-doc-14-nist-sp-800-53-p255-6', 0, 36, '14-nist-sp-800-53', 'retrieved', '6F8D973F27EF7169F7C06A2D20645B8E3522C95575B6F150B224C38122615879', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
