VALUES ('doc-14-nist-sp-800-53-p256-1', 'doc-14-nist-sp-800-53', '', 256, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 229 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p256-1', 0, 28, '14-nist-sp-800-53', 'retrieved', 'DC794248C041218346E3DF23D49A610F49D39BB6EE7162E65DC7F07522402044', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
