VALUES ('doc-14-nist-sp-800-53-p257-1', 'doc-14-nist-sp-800-53', '', 257, 'NIST SP 800-53, REV. 5 SECURITY AND PRIVACY CONTROLS FOR INFORMATION SYSTEMS AND ORGANIZATIONS _________________________________________________________________________________________________ CHAPTER THREE PAGE 230 This publication is available free of charge from: https://doi.org/10.6028/NIST.SP.800-53r5', 'kb-doc-14-nist-sp-800-53-p257-1', 0, 28, '14-nist-sp-800-53', 'retrieved', '103103B9C8E32BFC8A0137430EFB5AF47CC2EF95B826FD006900E15DFD88C31D', 'v1', '{"source_id": "14-nist-sp-800-53", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "REFERENCE_CONCEPT"}')
